const state = { connection: {...DEFAULT_CONNECTION}, session: null, profile: null, role: '', data: {}, page: 'overview', busy: false };

const esc = (v) => String(v ?? '—').replace(/[&<>'"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const money = (v) => new Intl.NumberFormat('en-KE',{style:'currency',currency:'KES',maximumFractionDigits:0}).format(Number(v || 0));
const date = (v) => v ? new Date(v).toLocaleString('en-KE',{dateStyle:'medium',timeStyle:'short'}) : '—';
const status = (v) => `<span class="badge ${String(v||'').toLowerCase().replaceAll(' ','-')}">${esc(v || 'unknown')}</span>`;
function toast(message, kind='ok') { const node=document.createElement('div'); node.className=`toast ${kind}`; node.textContent=message; document.body.append(node); setTimeout(()=>node.remove(),4200); }
function loading(label='Loading live data…') { return `<div class="empty"><div class="spinner"></div>${label}</div>`; }

async function request(path, options={}) {
  const url = `${state.connection.url.replace(/\/$/,'')}/${path.replace(/^\//,'')}`;
  const headers = { apikey: state.connection.key, Authorization: `Bearer ${state.session.access_token}`, ...(options.body ? {'Content-Type':'application/json'} : {}), ...(options.headers||{}) };
  const response = await fetch(url, {...options, headers});
  if (!response.ok) { const body = await response.text(); throw new Error(body || `Request failed (${response.status})`); }
  const text = await response.text(); return text ? JSON.parse(text) : null;
}
async function authenticate(email, password) {
  const url = `${state.connection.url.replace(/\/$/,'')}/auth/v1/token?grant_type=password`;
  const response = await fetch(url,{method:'POST',headers:{apikey:state.connection.key,'Content-Type':'application/json'},body:JSON.stringify({email,password})});
  if (!response.ok) throw new Error('Sign-in failed. Check your credentials and backend connection.');
  state.session = await response.json(); await window.dexAdmin.saveSession(state.session); await hydrateIdentity();
}
async function hydrateIdentity() {
  const uid = state.session.user.id;
  const [profiles, roles] = await Promise.all([
    request(`rest/v1/profiles?id=eq.${encodeURIComponent(uid)}&select=*`),
    request(`rest/v1/user_roles?user_id=eq.${encodeURIComponent(uid)}&select=*`)
  ]);
  state.profile = profiles?.[0] || {email:state.session.user.email,name:'Administrator'};
  state.role = roles?.[0]?.role || '';
  if (state.role.toLowerCase() !== 'admin') throw new Error('This account is not an administrator.');
}
async function refreshData() {
  state.busy=true; render();
  const queries = {
    packages: 'rest/v1/cargo_packages?select=*&order=registered_at.desc&limit=250',
    employees: 'api/public/admin/employees',
    notifications: 'rest/v1/payment_notifications?select=*&order=uploaded_at.desc&limit=100',
    commissions: 'rest/v1/commissions?select=*&order=created_at.desc&limit=150',
    audits: 'rest/v1/audit_logs?select=*&order=timestamp.desc&limit=100',
    broadcasts: 'rest/v1/broadcast_messages?select=*&order=created_at.desc&limit=50'
  };
  const entries = await Promise.all(Object.entries(queries).map(async ([key,path]) => {
    try { const value = await request(path); return [key, key==='employees' ? (value.employees || value || []) : (value || [])]; } catch (e) { console.warn(key,e); return [key,[]]; }
  }));
  state.data=Object.fromEntries(entries); state.busy=false; render();
}
function navItem(id, icon, label) { return `<button class="nav ${state.page===id?'active':''}" data-page="${id}"><span>${icon}</span>${label}</button>`; }
function shell(content) { return `<div class="shell"><aside><div class="brand"><div class="mark">D</div><div><b>DEX</b><small>ADMIN CONSOLE</small></div></div><div class="workspace">OPERATIONS</div>${navItem('overview','◫','Overview')}${navItem('shipments','▣','Shipments')}${navItem('payments','◉','Payments')}${navItem('staff','♚','Staff & access')}${navItem('commissions','◈','Commissions')}<div class="workspace">SYSTEM</div>${navItem('broadcasts','◌','Announcements')}${navItem('audit','◷','Audit trail')}<div class="side-bottom"><div class="admin-dot">${esc((state.profile?.name||'A').slice(0,1))}</div><div><b>${esc(state.profile?.name||'Administrator')}</b><small>System administrator</small></div><button id="signout" title="Sign out">↪</button></div></aside><main><header><div><p class="eyebrow">DEX LOGISTICS / CONTROL CENTER</p><h1>${({overview:'Operations overview',shipments:'Shipment control',payments:'Payment queue',staff:'Staff & access',commissions:'Commission center',broadcasts:'Announcements',audit:'Audit trail'})[state.page]}</h1></div><div class="top-actions"><span class="live"><i></i> LIVE BACKEND</span><button class="secondary" id="refresh">↻ Refresh</button></div></header>${content}</main></div>`; }
function metric(label,value,detail,accent='blue') { return `<article class="metric ${accent}"><span>${label}</span><strong>${value}</strong><small>${detail}</small></article>`; }
function overview() { const p=state.data.packages||[], n=state.data.notifications||[], c=state.data.commissions||[]; const collected=p.filter(x=>['collected','delivered'].includes((x.status||'').toLowerCase())).length, revenue=p.reduce((a,x)=>a+Number(x.amount_due||0),0), pending=n.filter(x=>x.status==='pending').length; const recent=p.slice(0,6); return `<section class="metrics">${metric('Total shipments',p.length,'All time records','blue')}${metric('Collected',collected,`${p.length?Math.round(collected/p.length*100):0}% completion rate`,'green')}${metric('Expected revenue',money(revenue),'From loaded shipments','amber')}${metric('Payment review',pending, pending?'Needs attention':'All caught up','red')}</section><section class="grid two"><article class="panel"><div class="panel-head"><div><h2>Shipment flow</h2><p>Current operational distribution</p></div></div><div class="flow">${['received','in transit','arrived','cleared','collected'].map(s=>{const count=p.filter(x=>(x.status||'').toLowerCase()===s).length;return `<div><b>${count}</b><span>${s}</span><i style="width:${p.length?Math.max(8,count/p.length*100):8}%"></i></div>`}).join('')}</div></article><article class="panel attention"><div class="panel-head"><div><h2>Action center</h2><p>Prioritize these items next</p></div></div><button class="action" data-goto="payments"><span>◉</span><div><b>${pending} payment notification${pending===1?'':'s'} awaiting review</b><small>Open payment queue</small></div>›</button><button class="action" data-goto="commissions"><span>◈</span><div><b>${c.filter(x=>x.status==='pending').length} pending commission${c.filter(x=>x.status==='pending').length===1?'':'s'}</b><small>Review employee earnings</small></div>›</button></article></section><section class="panel"><div class="panel-head"><div><h2>Recent shipments</h2><p>Latest records synchronised from the mobile backend</p></div><button class="text-btn" data-goto="shipments">View all →</button></div>${shipmentTable(recent)}</section>`; }
function shipmentTable(rows) { return rows.length?`<div class="table-wrap"><table><thead><tr><th>Tracking</th><th>Consignee</th><th>Route</th><th>Amount due</th><th>Status</th><th></th></tr></thead><tbody>${rows.map(x=>`<tr><td><b>${esc(x.tracking_number)}</b></td><td>${esc(x.consignee_name||x.customers?.name)}</td><td>${esc(x.origin)} <span class="muted">→</span> ${esc(x.destination)}</td><td>${money(x.amount_due)}</td><td>${status(x.status)}</td><td><button class="row-btn" data-track="${esc(x.tracking_number)}">Manage</button></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">No shipments returned by the backend.</div>`; }
