function payments() { const rows=state.data.notifications||[]; return `<section class="panel"><div class="panel-head"><div><h2>Payment notifications</h2><p>Mobile payment evidence, STK results and allocations</p></div><span class="count">${rows.length} records</span></div><div class="table-wrap"><table><thead><tr><th>Reference</th><th>Phone</th><th>Amount</th><th>Evidence</th><th>Received</th><th>Status</th></tr></thead><tbody>${rows.map(x=>`<tr><td><b>${esc(x.mpesa_receipt||x.notification_number||x.id)}</b></td><td>${esc(x.sender_phone)}</td><td>${money(x.amount)}</td><td>${esc(x.evidence_type)}</td><td>${date(x.uploaded_at||x.timestamp)}</td><td>${status(x.status)}</td></tr>`).join('')}</tbody></table></div></section>`; }
