function commissions() { const rows=state.data.commissions||[]; return `<section class="panel"><div class="panel-head"><div><h2>Employee commissions</h2><p>Approve validated earnings and record payments.</p></div><span class="count">${money(rows.filter(x=>x.status!=='paid').reduce((a,x)=>a+Number(x.amount||0),0))} outstanding</span></div><div class="table-wrap"><table><thead><tr><th>Reference</th><th>Employee</th><th>Gross profit</th><th>Rate</th><th>Commission</th><th>Status</th><th>Action</th></tr></thead><tbody>${rows.map(x=>`<tr><td><b>${esc(x.reference||x.order_id)}</b></td><td>${esc(x.employee_id)}</td><td>${money(x.gross_profit)}</td><td>${Number(x.rate||0)}%</td><td>${money(x.amount)}</td><td>${status(x.status)}</td><td>${x.status==='pending'?`<button class="row-btn approve" data-commission="${x.id}">Approve</button>`:x.status==='approved'?`<button class="row-btn paid" data-paid="${x.id}">Mark paid</button>`:'—'}</td></tr>`).join('')}</tbody></table></div></section>`; }
function broadcasts() { const rows=state.data.broadcasts||[]; return `<section class="grid broadcast-grid"><article class="panel compose"><h2>Send announcement</h2><p>Broadcast a concise operational update to the target group.</p><form id="broadcast-form"><label>Audience<select name="target"><option value="all">All staff</option><option value="sales">Sales team</option><option value="operations">Operations</option></select></label><label>Message<textarea name="message" maxlength="500" placeholder="Write an important update…" required></textarea></label><button class="primary" type="submit">Send announcement →</button></form></article><article class="panel"><div class="panel-head"><div><h2>Recent announcements</h2><p>Distributed via the connected backend</p></div></div><div class="timeline">${rows.map(x=>`<div><i></i><b>${esc(x.message)}</b><small>${esc(x.target)} · ${date(x.created_at||x.timestamp)}</small></div>`).join('')||'<div class="empty">No announcements yet.</div>'}</div></article></section>`; }
function audit() { const rows=state.data.audits||[]; return `<section class="toolbar"><p class="muted">Immutable operational record from the backend.</p><button class="secondary" id="export-audit">⇩ Export CSV</button></section><section class="panel"><div class="table-wrap"><table><thead><tr><th>Time</th><th>Action</th><th>Actor</th><th>Details</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${date(x.timestamp)}</td><td>${status(x.action)}</td><td>${esc(x.actor)}</td><td>${esc(x.details)}</td></tr>`).join('')}</tbody></table></div></section>`; }
function render() { if (!state.session) return renderLogin(); const view=state.busy?loading():({overview,shipments,payments,staff,commissions,broadcasts,audit})[state.page](); app.innerHTML=shell(view); bind(); }
function renderLogin() { const configured=state.connection.url&&state.connection.key; app.innerHTML=`<div class="login"><div class="login-art"><div class="orb"></div><div class="login-brand"><div class="mark">D</div><b>DEX</b><span>LOGISTICS CONTROL</span></div><h1>Move faster.<br><em>See everything.</em></h1><p>A focused operations workspace for the people keeping cargo moving.</p><div class="feature-list"><span>◉ Live backend data</span><span>◈ Role-protected actions</span><span>◷ Secure local session</span></div></div><div class="login-card"><p class="eyebrow">${configured?'ADMINISTRATOR SIGN IN':'CONNECT BACKEND'}</p><h2>${configured?'Welcome back':'One-time connection setup'}</h2><p>${configured?'Use your existing active DEX admin account.':'Use the same Supabase URL and publishable key as the mobile app.'}</p>${configured?`<form id="login-form"><label>Email<input required type="email" name="email" placeholder="admin@company.com"></label><label>Password<input required type="password" name="password" placeholder="••••••••"></label><button class="primary wide">Sign in to console →</button></form><button class="link-btn" id="change-connection">Change backend connection</button>`:`<form id="setup-form"><label>Supabase project URL<input required type="url" name="url" placeholder="https://your-project.supabase.co"></label><label>Publishable / anon key<input required name="key" placeholder="sb_publishable_…"></label><button class="primary wide">Save and continue →</button></form>`}</div></div>`; $('#login-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target);try{e.target.querySelector('button').textContent='Signing in…';await authenticate(f.get('email'),f.get('password'));await refreshData()}catch(err){toast(err.message,'error');e.target.querySelector('button').textContent='Sign in to console →'}}); $('#setup-form')?.addEventListener('submit',async e=>{e.preventDefault();state.connection=Object.fromEntries(new FormData(e.target));await window.dexAdmin.saveConnection(state.connection);renderLogin();}); $('#change-connection')?.addEventListener('click',async()=>{state.connection={};await window.dexAdmin.saveConnection({});renderLogin()}); }
function bind() { document.querySelectorAll('[data-page],[data-goto]').forEach(b=>b.addEventListener('click',()=>{state.page=b.dataset.page||b.dataset.goto;render()})); $('#refresh')?.addEventListener('click',refreshData); $('#signout')?.addEventListener('click',async()=>{await window.dexAdmin.clearSession();state.session=null;state.data={};renderLogin()}); $('#shipment-search')?.addEventListener('input',e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('tbody tr').forEach(row=>row.hidden=!row.textContent.toLowerCase().includes(q))}); document.querySelectorAll('[data-employee]').forEach(b=>b.addEventListener('click',()=>setEmployee(b.dataset.employee,b.dataset.active!=='true'))); document.querySelectorAll('[data-commission]').forEach(b=>b.addEventListener('click',()=>commission(b.dataset.commission,'approve_commission'))); document.querySelectorAll('[data-paid]').forEach(b=>b.addEventListener('click',()=>commission(b.dataset.paid,'mark_commission_paid'))); $('#broadcast-form')?.addEventListener('submit',sendBroadcast); $('#export-audit')?.addEventListener('click',exportAudit); document.querySelectorAll('[data-track]').forEach(b=>b.addEventListener('click',()=>openShipment(b.dataset.track))); $('#add-staff')?.addEventListener('click',addStaff); $('#new-shipment')?.addEventListener('click',()=>toast('Shipment registration remains available in the mobile receiving workflow.','error')); }
async function setEmployee(id,is_active) { try { await request('api/public/admin/employees',{method:'PATCH',body:JSON.stringify({employee_id:id,is_active})});toast(`Account ${is_active?'activated':'deactivated'}.`);await refreshData();}catch(e){toast(`Access update failed: ${e.message}`,'error')} }
