function exportAudit(){const rows=state.data.audits||[];const csv=['Time,Action,Actor,Details',...rows.map(x=>[x.timestamp,x.action,x.actor,x.details].map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(','))].join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download=`dex-audit-${new Date().toISOString().slice(0,10)}.csv`;a.click();URL.revokeObjectURL(a.href);}
