function renderLogin() {
  app.innerHTML = `<div class="login"><div class="login-art"><div class="orb"></div><div class="login-brand"><img style="width:240px;border-radius:12px" src="assets/dex-logo.png" alt="DEX Logistics"></div><h1>Move faster.<br><em>See everything.</em></h1><p>A focused operations workspace for the people keeping DEX Logistics cargo moving.</p><div class="feature-list"><span>◉ Live backend data</span><span>◈ Role-protected actions</span><span>◷ Secure local session</span></div></div><div class="login-card"><img style="width:96px;border-radius:10px;margin-bottom:18px" src="assets/dex-logo.png" alt="DEX Logistics"><p class="eyebrow">DEX LOGISTICS · ADMINISTRATOR SIGN IN</p><h2>Welcome back</h2><p>Sign in with your active DEX administrator account.</p><form id="login-form"><label>Email<input required type="email" name="email" placeholder="admin@dexcargo.com"></label><label>Password<input required type="password" name="password" placeholder="••••••••"></label><button class="primary wide">Sign in to console →</button></form></div></div>`;
  $('#login-form').addEventListener('submit', async e => { e.preventDefault(); const f = new FormData(e.target); try { await authenticate(f.get('email'), f.get('password')); await refreshData(); } catch (err) { toast(err.message, 'error'); } });
}
async function request(path, options = {}, retried = false) {
  const url = `${state.connection.url.replace(/\/$/, '')}/${path.replace(/^\//, '')}`;
  const headers = { apikey: state.connection.key, Authorization: `Bearer ${state.session.access_token}`, ...(options.body ? {'Content-Type':'application/json'} : {}), ...(options.headers || {}) };
  const response = await fetch(url, {...options, headers});
  if (response.status === 401 && !retried && state.session.refresh_token) {
    const refresh = await fetch(`${state.connection.url}/auth/v1/token?grant_type=refresh_token`, {method:'POST', headers:{apikey:state.connection.key,'Content-Type':'application/json'}, body:JSON.stringify({refresh_token:state.session.refresh_token})});
    if (refresh.ok) { state.session = await refresh.json(); await window.dexAdmin.saveSession(state.session); return request(path, options, true); }
  }
  if (!response.ok) { const body = await response.text(); throw new Error(body || `Request failed (${response.status})`); }
  const text = await response.text(); return text ? JSON.parse(text) : null;
}
async function refreshData() {
  state.busy = true; render();
  const sources = { packages:'rest/v1/cargo_packages?select=*&order=registered_at.desc&limit=250', notifications:'rest/v1/payment_notifications?select=*&order=uploaded_at.desc&limit=100', commissions:'rest/v1/commissions?select=*&order=created_at.desc&limit=150', audits:'rest/v1/audit_logs?select=*&order=timestamp.desc&limit=100', broadcasts:'rest/v1/broadcast_messages?select=*&order=timestamp.desc&limit=50', employees:'api/public/admin/employees' };
  const results = await Promise.all(Object.entries(sources).map(async ([name,path]) => { try { const value = await request(path); return [name, name === 'employees' ? (value.employees || value || []) : (value || [])]; } catch (error) { console.error(name,error); return [name,[]]; } }));
  state.data = Object.fromEntries(results); state.busy = false; render();
}
function shipmentTable(rows) { return rows.length ? `<div class="table-wrap"><table><thead><tr><th>Tracking</th><th>Consignee</th><th>Route</th><th>Amount due</th><th>Status</th><th>Operation</th></tr></thead><tbody>${rows.map(x => `<tr><td><b>${esc(x.id)}</b></td><td>${esc(x.consignee)}</td><td>${esc(x.origin)} <span class="muted">→</span> ${esc(x.dest)}</td><td>${money(x.cost)}</td><td>${status(x.status)}</td><td><button class="row-btn" data-track="${esc(x.id)}">Update status</button></td></tr>`).join('')}</tbody></table></div>` : `<div class="empty">No cargo records returned by the backend.</div>`; }
function overview() { const p=state.data.packages||[], n=state.data.notifications||[], c=state.data.commissions||[]; const collected=p.filter(x=>x.status==='collected').length, revenue=p.reduce((a,x)=>a+Number(x.cost||0),0), pending=n.filter(x=>(x.status||'').toUpperCase()==='PENDING').length; return `<section class="metrics">${metric('Total shipments',p.length,'Live cargo records','blue')}${metric('Collected',collected,`${p.length?Math.round(collected/p.length*100):0}% completion rate`,'green')}${metric('Cargo value',money(revenue),'From live cargo records','amber')}${metric('Payment review',pending,pending?'Needs attention':'All caught up','red')}</section><section class="panel"><div class="panel-head"><div><h2>Recent cargo</h2><p>Synced from cargo_packages</p></div></div>${shipmentTable(p.slice(0,12))}</section>`; }
async function commission(id, rpc) { try { const body = rpc === 'approve_commission' ? {_id:id} : {_id:id,_reference:prompt('M-Pesa/payment reference') || ''}; if (rpc !== 'approve_commission' && !body._reference) return; await request(`rest/v1/rpc/${rpc}`, {method:'POST',body:JSON.stringify(body)}); toast(rpc==='approve_commission'?'Commission approved.':'Commission marked paid.'); await refreshData(); } catch(e) { toast(`Action failed: ${e.message}`,'error'); } }
async function openShipment(id) { const cargo=(state.data.packages||[]).find(x=>x.id===id); const next=prompt(`Update ${id}: registered, paid, or collected`, cargo?.status || 'registered'); if (!next || !['registered','paid','collected'].includes(next.toLowerCase())) return toast('Choose registered, paid, or collected.','error'); const patch={status:next.toLowerCase()}; if (patch.status==='paid') patch.paid_at=new Date().toISOString(); if (patch.status==='collected') patch.collected_at=new Date().toISOString(); try { await request(`rest/v1/cargo_packages?id=eq.${encodeURIComponent(id)}`, {method:'PATCH',headers:{Prefer:'return=representation'},body:JSON.stringify(patch)}); toast(`Cargo ${id} updated.`); await refreshData(); } catch(e) { toast(`Status update failed: ${e.message}`,'error'); } }
async function refreshData() {
  state.busy=true; render();
  const get = async path => { try { return await request(path); } catch (e) { console.warn(path,e); return []; } };
  const [packages, notifications, commissions, audits, broadcasts, directEmployees] = await Promise.all([
    get('rest/v1/cargo_packages?select=*&order=registered_at.desc&limit=500'), get('rest/v1/payment_notifications?select=*&order=uploaded_at.desc&limit=200'),
    get('rest/v1/commissions?select=*&order=created_at.desc&limit=300'), get('rest/v1/audit_logs?select=*&order=timestamp.desc&limit=150'),
    get('rest/v1/broadcast_messages?select=*&order=timestamp.desc&limit=50'), get('rest/v1/employees?select=*&order=full_name.asc')
  ]);
  let employees = directEmployees;
  if (!employees.length) { try { const api = await request('api/public/admin/employees'); employees = api.employees || api || []; } catch {} }
  state.data={packages,notifications,commissions,audits,broadcasts,employees}; state.busy=false; render();
}
function shipmentTable(rows) { return rows.length?`<div class="table-wrap"><table><thead><tr><th>Photo</th><th>Tracking</th><th>Consignee</th><th>Route</th><th>Amount</th><th>Status</th><th>Actions</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${x.package_photo_url?`<button class="photo-btn" data-photo="${esc(x.package_photo_url)}">View</button>`:'<span class="muted">No photo</span>'}</td><td><b>${esc(x.id)}</b></td><td>${esc(x.consignee)}<br><small>${esc(x.phone)}</small></td><td>${esc(x.origin)} → ${esc(x.dest)}</td><td>${money(x.cost)}</td><td>${status(x.status)}</td><td><button class="row-btn" data-track="${esc(x.id)}">Update</button> <button class="row-btn" data-reminder="${esc(x.id)}">Reminder</button></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">No cargo records returned by the backend.</div>`; }
function overview() { const p=state.data.packages||[], people=new Set(p.map(x=>x.phone).filter(Boolean)).size, paid=p.filter(x=>x.status==='paid').length, collected=p.filter(x=>x.status==='collected').length, registered=p.filter(x=>x.status==='registered').length; const max=Math.max(1,registered,paid,collected); return `<section class="metrics">${metric('Packages registered',p.length,'Live cargo records','blue')}${metric('Clients served',people,'Unique consignee phones','green')}${metric('Ready for collection',paid,'Paid packages in warehouse','amber')}${metric('Collected',collected,'Completed handovers','red')}</section><section class="grid two"><article class="panel"><div class="panel-head"><div><h2>Cargo lifecycle</h2><p>Live distribution from cargo_packages</p></div></div><div class="flow">${[['registered',registered],['paid',paid],['collected',collected]].map(([name,count])=>`<div><b>${count}</b><span>${name}</span><i style="width:${Math.max(8,count/max*100)}%"></i></div>`).join('')}</div></article><article class="panel"><div class="panel-head"><div><h2>Revenue view</h2><p>Registered cargo value</p></div></div><div class="metric green"><span>Total cargo value</span><strong>${money(p.reduce((sum,x)=>sum+Number(x.cost||0),0))}</strong><small>${state.data.commissions?.length||0} commission records · ${(state.data.employees||[]).length} staff</small></div></article></section><section class="panel"><div class="panel-head"><div><h2>Latest packages</h2><p>Photo, status and reminder actions</p></div></div>${shipmentTable(p.slice(0,10))}</section>`; }
async function viewPhoto(path) { try { const url=`${state.connection.url}/storage/v1/object/${path.replace(/^\//,'')}`; const response=await fetch(url,{headers:{apikey:state.connection.key,Authorization:`Bearer ${state.session.access_token}`}}); if(!response.ok) throw new Error('Photo unavailable'); const objectUrl=URL.createObjectURL(await response.blob()); const w=window.open(); w.document.write(`<title>DEX package photo</title><img src="${objectUrl}" style="max-width:100%;height:auto">`); } catch(e){toast(e.message,'error');} }
async function copyReminder(id) { const pkg=(state.data.packages||[]).find(x=>x.id===id); if(!pkg)return; const language=prompt('Type EN for English or ZH for Chinese','EN'); const name=pkg.consignee||'Customer'; const english=`Hello ${name}, this is DEX Cargo. This is a reminder that your package (${pkg.id}) is currently in our warehouse in Nairobi. Please come and pick it up. Thank you.`; const chinese=`您好，${name}。这里是 DEX Cargo。提醒您：您的包裹（${pkg.id}）目前在我们内罗毕的仓库。请您前来领取。谢谢。`; await navigator.clipboard.writeText(String(language).toUpperCase()==='ZH'?chinese:english); toast('Client reminder copied to clipboard.'); }
