function overview() { const p=state.data.packages||[], staff=state.data.employees||[], commissions=state.data.commissions||[], people=new Set(p.map(x=>x.phone).filter(Boolean)).size, paid=p.filter(x=>x.status==='paid').length, collected=p.filter(x=>x.status==='collected').length, registered=p.filter(x=>x.status==='registered').length, max=Math.max(1,registered,paid,collected); return `<section class="metrics">${metric('Packages registered',p.length,'Live cargo records','blue')}${metric('Clients served',people,'Unique consignee phones','green')}${metric('Active staff',staff.filter(x=>x.is_active).length,`${staff.length} employee records from backend`,'amber')}${metric('Commissions',commissions.length,commissions.length?'Live commission records':'No commission records in backend','red')}</section><section class="grid two"><article class="panel"><div class="panel-head"><div><h2>Cargo lifecycle</h2><p>Live distribution from cargo_packages</p></div></div><div class="flow">${[['registered',registered],['paid',paid],['collected',collected]].map(([name,count])=>`<div><b>${count}</b><span>${name}</span><i style="width:${Math.max(8,count/max*100)}%"></i></div>`).join('')}</div></article><article class="panel"><div class="panel-head"><div><h2>Live employee roster</h2><p>Directly from employees table</p></div><button class="text-btn" data-goto="staff">Open staff →</button></div>${staff.length?staff.slice(0,5).map(x=>`<div class="action"><span>◉</span><div><b>${esc(x.full_name)} · ${esc(x.employee_code)}</b><small>${esc(x.role)} · ${x.is_active?'Active':'Inactive'}</small></div></div>`).join(''):'<div class="empty">No employee rows returned.</div>'}</article></section><section class="panel"><div class="panel-head"><div><h2>Latest packages</h2><p>Photo, status and reminder actions</p></div></div>${shipmentTable(p.slice(0,10))}</section>`; }
const ADMIN_BACKEND = 'https://project--5e9b81ad-6c63-4331-af7a-01008019e17f.lovable.app';
async function adminRequest(path, options={}) { const response = await fetch(`${ADMIN_BACKEND}${path}`, {...options,headers:{Authorization:`Bearer ${state.session.access_token}`,...(options.body?{'Content-Type':'application/json'}:{}),...(options.headers||{})}}); if(!response.ok) throw new Error(await response.text() || `Admin request failed (${response.status})`); const text=await response.text(); return text?JSON.parse(text):null; }
async function refreshData() { state.busy=true; render(); const get=async p=>{try{return await request(p)}catch(e){console.warn(e);return[]}}; const [packages,notifications,commissions,audits,broadcasts,employees]=await Promise.all([get('rest/v1/cargo_packages?select=*&order=registered_at.desc&limit=500'),get('rest/v1/payment_notifications?select=*&order=uploaded_at.desc&limit=200'),get('rest/v1/commissions?select=*&order=created_at.desc&limit=300'),get('rest/v1/audit_logs?select=*&order=timestamp.desc&limit=150'),get('rest/v1/broadcast_messages?select=*&order=timestamp.desc&limit=50'),adminRequest('/api/public/admin/employees').then(x=>x.employees||[]).catch(()=>get('rest/v1/employees?select=*&order=full_name.asc'))]); state.data={packages,notifications,commissions,audits,broadcasts,employees};state.busy=false;render(); }
function staff() { const rows=state.data.employees||[]; return `<section class="toolbar"><p class="muted">Manage staff through the secured DEX administrator backend.</p><button class="primary" id="add-staff">+ Add team member</button></section><section class="panel"><div class="table-wrap"><table><thead><tr><th>Employee</th><th>Code</th><th>Role</th><th>Contact</th><th>Commission</th><th>Access</th><th></th></tr></thead><tbody>${rows.map(x=>`<tr><td><b>${esc(x.full_name)}</b><br><small>${esc(x.email)}</small></td><td>${esc(x.employee_code)}</td><td>${status(x.role)}</td><td>${esc(x.phone)}</td><td>${x.commission_percentage??0}%</td><td><button class="toggle ${x.is_active?'on':''}" data-employee="${x.id}" data-active="${x.is_active}"><i></i>${x.is_active?'Active':'Inactive'}</button></td><td>${x.role==='admin'?'—':`<button class="row-btn" data-delete-employee="${x.id}">Delete</button>`}</td></tr>`).join('')}</tbody></table></div></section>`; }
function payments() { const rows=state.data.notifications||[]; return `<section class="grid broadcast-grid"><article class="panel compose"><h2>Upload payment evidence</h2><p>Admin uploads an image or text; staff can link it to cargo.</p><form id="payment-upload"><label>Evidence type<select name="evidence_type"><option value="IMAGE">Screenshot / image</option><option value="TEXT">Text / M-Pesa message</option></select></label><label>Screenshot<input name="image" type="file" accept="image/*"></label><label>Payment text<textarea name="text_content" placeholder="Paste M-Pesa or payment message"></textarea></label><label>Amount (KES)<input name="amount" type="number" min="1"></label><label>Sender phone<input name="sender_phone" placeholder="07…"></label><button class="primary" type="submit">Upload payment evidence</button></form></article><article class="panel"><div class="panel-head"><div><h2>Payment queue</h2><p>Link a payment to its package.</p></div></div><div class="table-wrap"><table><thead><tr><th>Reference</th><th>Amount</th><th>Phone</th><th>Status</th><th></th></tr></thead><tbody>${rows.map(x=>`<tr><td><b>${esc(x.notification_number||x.id)}</b></td><td>${money(x.amount)}</td><td>${esc(x.sender_phone)}</td><td>${status(x.status)}</td><td>${(x.status||'').toUpperCase()==='LINKED'?'Linked':`<button class="row-btn" data-link-payment="${x.id}">Link package</button>`}</td></tr>`).join('')}</tbody></table></div></article></section>`; }
async function createEmployee() { const full_name=prompt('Full name'); if(!full_name)return; const email=prompt('Email'); const password=prompt('Temporary password (8+ characters)'); const phone=prompt('Phone (optional)')||null; const role=prompt('Role: sales_rep, logistics_manager, sales_manager, or admin','sales_rep'); const commission_percentage=Number(prompt('Commission percentage','0')); try{await adminRequest('/api/public/admin/employees',{method:'POST',body:JSON.stringify({full_name,email,password,phone,role,commission_percentage})});toast('Team member created.');await refreshData()}catch(e){toast(e.message,'error')} }
async function deleteEmployee(id) { if(!confirm('Permanently delete this employee and their login?'))return; try{await adminRequest('/api/public/admin/delete-user',{method:'POST',body:JSON.stringify({employee_id:id})});toast('Employee deleted.');await refreshData()}catch(e){toast(e.message,'error')} }
async function uploadPayment(form) { const f=new FormData(form), type=f.get('evidence_type'), file=f.get('image'); if(type==='IMAGE'&&(!file||!file.size))return toast('Choose a screenshot.','error'); if(type==='TEXT'&&!f.get('text_content').trim())return toast('Enter payment text.','error'); let image_url=null; try{if(type==='IMAGE'){const filename=`payment_${Date.now()}_${file.name.replace(/[^a-zA-Z0-9._-]/g,'_')}`;const r=await fetch(`${state.connection.url}/storage/v1/object/proofs/${filename}`,{method:'POST',headers:{apikey:state.connection.key,Authorization:`Bearer ${state.session.access_token}`,'Content-Type':file.type},body:file});if(!r.ok)throw new Error(await r.text());image_url=`proofs/${filename}`;}const id=`PN-${Date.now()}`, notification_number=`PAY-${new Date().toISOString().slice(0,10).replaceAll('-','')}-${Date.now().toString().slice(-4)}`;await request('rest/v1/payment_notifications',{method:'POST',headers:{Prefer:'return=representation'},body:JSON.stringify({id,notification_number,evidence_type:type,image_url,text_content:f.get('text_content')||null,uploaded_by:state.profile?.name||'Admin',uploaded_at:new Date().toISOString(),status:'PENDING',amount:Number(f.get('amount'))||null,sender_phone:f.get('sender_phone')||null,timestamp:new Date().toISOString()})});toast('Payment evidence uploaded.');await refreshData()}catch(e){toast(`Upload failed: ${e.message}`,'error')} }
async function linkPayment(id) { const pkgId=prompt('Tracking number to link'); if(!pkgId)return; const n=(state.data.notifications||[]).find(x=>x.id===id); try{await request('rest/v1/payment_allocations',{method:'POST',headers:{Prefer:'return=representation'},body:JSON.stringify({id:`PA-${Date.now()}`,payment_notification_id:id,order_id:pkgId,tracking_number:pkgId,allocated_amount:Number(n?.amount)||0,linked_by:state.profile?.name||'Admin',linked_at:new Date().toISOString(),notification_number:n?.notification_number||null})});toast('Payment linked to package.');await refreshData()}catch(e){toast(`Link failed: ${e.message}`,'error')} }
function bind() { document.querySelectorAll('[data-page],[data-goto]').forEach(b=>b.addEventListener('click',()=>{state.page=b.dataset.page||b.dataset.goto;render()})); $('#refresh')?.addEventListener('click',refreshData); $('#signout')?.addEventListener('click',async()=>{await window.dexAdmin.clearSession();state.session=null;state.data={};renderLogin()}); $('#add-staff')?.addEventListener('click',createEmployee); $('#payment-upload')?.addEventListener('submit',e=>{e.preventDefault();uploadPayment(e.target)}); document.querySelectorAll('[data-delete-employee]').forEach(b=>b.addEventListener('click',()=>deleteEmployee(b.dataset.deleteEmployee))); document.querySelectorAll('[data-link-payment]').forEach(b=>b.addEventListener('click',()=>linkPayment(b.dataset.linkPayment))); document.querySelectorAll('[data-employee]').forEach(b=>b.addEventListener('click',()=>setEmployee(b.dataset.employee,b.dataset.active!=='true'))); document.querySelectorAll('[data-commission]').forEach(b=>b.addEventListener('click',()=>commission(b.dataset.commission,'approve_commission'))); document.querySelectorAll('[data-paid]').forEach(b=>b.addEventListener('click',()=>commission(b.dataset.paid,'mark_commission_paid'))); document.querySelectorAll('[data-track]').forEach(b=>b.addEventListener('click',()=>openShipment(b.dataset.track))); document.querySelectorAll('[data-photo]').forEach(b=>b.addEventListener('click',()=>viewPhoto(b.dataset.photo))); document.querySelectorAll('[data-reminder]').forEach(b=>b.addEventListener('click',()=>copyReminder(b.dataset.reminder))); $('#broadcast-form')?.addEventListener('submit',sendBroadcast); $('#export-audit')?.addEventListener('click',exportAudit); }
async function setEmployee(id,is_active) { try { await adminRequest('/api/public/admin/employees',{method:'PATCH',body:JSON.stringify({employee_id:id,is_active})});toast(`Account ${is_active?'activated':'deactivated'}.`);await refreshData();}catch(e){toast(`Access update failed: ${e.message}`,'error')} }
function commissions() { const rows=state.data.commissions||[], staff=state.data.employees||[]; const byEmployee=staff.map(e=>({...e,total:rows.filter(c=>c.employee_id===e.id||c.employee_id===e.employee_code).reduce((sum,c)=>sum+Number(c.amount||0),0),pending:rows.filter(c=>(c.employee_id===e.id||c.employee_id===e.employee_code)&&c.status!=='paid').reduce((sum,c)=>sum+Number(c.amount||0),0)})); return `<section class="panel"><div class="panel-head"><div><h2>Commission accumulation by employee</h2><p>Totals from live commission records.</p></div><span class="count">${rows.length} records</span></div><div class="table-wrap"><table><thead><tr><th>Employee</th><th>Role</th><th>Accumulated</th><th>Outstanding</th></tr></thead><tbody>${byEmployee.map(e=>`<tr><td><b>${esc(e.full_name)}</b><br><small>${esc(e.employee_code)}</small></td><td>${esc(e.role)}</td><td>${money(e.total)}</td><td>${money(e.pending)}</td></tr>`).join('')||'<tr><td colspan="4">No employees returned.</td></tr>'}</tbody></table></div></section><section class="panel"><div class="panel-head"><div><h2>Commission ledger</h2><p>Approve or mark payment against each backend record.</p></div></div>${rows.length?`<div class="table-wrap"><table><thead><tr><th>Reference</th><th>Employee</th><th>Amount</th><th>Status</th><th></th></tr></thead><tbody>${rows.map(c=>`<tr><td>${esc(c.reference||c.order_id)}</td><td>${esc(c.employee_id)}</td><td>${money(c.amount)}</td><td>${status(c.status)}</td><td>${c.status==='pending'?`<button class="row-btn" data-commission="${c.id}">Approve</button>`:c.status==='approved'?`<button class="row-btn" data-paid="${c.id}">Mark paid</button>`:'—'}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No commission rows exist yet. The backend creates them when paid cargo has an eligible assigned sales representative and active commission rule.</div>'}</section>`; }
function broadcasts() { const rows=state.data.broadcasts||[], roles=[['all','All employees'],['sales_rep','Sales representatives'],['sales_manager','Sales managers'],['logistics_manager','Logistics managers'],['admin','Administrators']]; return `<section class="grid broadcast-grid"><article class="panel compose"><h2>Send announcement</h2><p>Send a role-specific operational update.</p><form id="broadcast-form"><label>Department / audience<select name="target">${roles.map(([value,label])=>`<option value="${value}">${label}</option>`).join('')}</select></label><label>Message<textarea name="message" maxlength="500" placeholder="Write an operational update…" required></textarea></label><button class="primary" type="submit">Send announcement →</button></form></article><article class="panel"><div class="panel-head"><div><h2>Recent announcements</h2><p>Distributed through the backend</p></div></div><div class="timeline">${rows.map(x=>`<div><i></i><b>${esc(x.message)}</b><small>${esc(x.target)} · ${date(x.created_at||x.timestamp)}</small></div>`).join('')||'<div class="empty">No announcements yet.</div>'}</div></article></section>`; }
function createEmployee() { const modal=document.createElement('div'); modal.style.cssText='position:fixed;inset:0;background:#020a11c9;z-index:30;display:grid;place-items:center;padding:20px'; modal.innerHTML=`<div style="position:relative;width:min(520px,100%);background:#0d1e2b;border:1px solid #34536a;border-radius:16px;padding:28px"><button class="modal-close" style="position:absolute;right:15px;top:10px;border:0;background:transparent;color:white;font-size:24px">×</button><p class="eyebrow">DEX LOGISTICS · STAFF ACCESS</p><h2>Add team member</h2><form id="employee-form"><label>Full name<input name="full_name" required></label><label>Email<input name="email" type="email" required></label><label>Temporary password<input name="password" type="password" minlength="8" required></label><label>Phone<input name="phone" placeholder="+254…"></label><label>Company role<select name="role"><option value="sales_rep">Sales representative</option><option value="sales_manager">Sales manager</option><option value="logistics_manager">Logistics manager</option><option value="admin">Administrator</option></select></label><label>Commission percentage<input name="commission_percentage" type="number" min="0" max="100" value="0" step="0.1"></label><button class="primary wide">Create team member</button></form></div>`; document.body.append(modal); modal.querySelector('.modal-close').onclick=()=>modal.remove(); modal.querySelector('#employee-form').onsubmit=async e=>{e.preventDefault();const form=e.target,body=Object.fromEntries(new FormData(form));body.commission_percentage=Number(body.commission_percentage);body.phone=body.phone||null;try{await adminRequest('/api/public/admin/employees',{method:'POST',body:JSON.stringify(body)});modal.remove();toast('Team member created successfully.');await refreshData()}catch(err){toast(`Create user failed: ${err.message}`,'error')}}; }
