async function adminRequest(path, options={}, retried=false) { const call=()=>fetch(`${ADMIN_BACKEND}${path}`, {...options,headers:{Authorization:`Bearer ${state.session.access_token}`,...(options.body?{'Content-Type':'application/json'}:{}),...(options.headers||{})}}); let response=await call(); if(response.status===401&&!retried&&state.session.refresh_token){const refresh=await fetch(`${state.connection.url}/auth/v1/token?grant_type=refresh_token`,{method:'POST',headers:{apikey:state.connection.key,'Content-Type':'application/json'},body:JSON.stringify({refresh_token:state.session.refresh_token})});if(refresh.ok){state.session=await refresh.json();await window.dexAdmin.saveSession(state.session);return adminRequest(path,options,true)}} if(!response.ok)throw new Error(await response.text()||`Admin request failed (${response.status})`);const text=await response.text();return text?JSON.parse(text):null;}
function shipments(){const rows=state.data.packages||[];return `<section class="toolbar"><div class="search"><span>⌕</span><input id="shipment-search" placeholder="Search package, client or phone"></div></section><section class="panel"><div class="panel-head"><div><h2>Packages</h2><p>Package records and condition images</p></div></div>${shipmentTable(rows)}</section>`;}
function payments(){const rows=state.data.notifications||[];return `<section class="panel compose"><div class="panel-head"><div><h2>New payment evidence</h2><p>Upload a screenshot or paste a customer payment message.</p></div></div><form id="payment-upload"><label>Evidence type<select name="evidence_type"><option value="IMAGE">Payment screenshot</option><option value="TEXT">Payment text</option></select></label><label>Screenshot<input name="image" type="file" accept="image/*"></label><label>Payment message<textarea name="text_content" placeholder="Paste the M-Pesa message here"></textarea></label><label>Amount (KES)<input name="amount" type="number" min="1"></label><label>Customer phone<input name="sender_phone" placeholder="07…"></label><button class="primary" type="submit">Save payment evidence</button></form></section><section class="panel"><div class="panel-head"><div><h2>Unlinked payments</h2><p>Link evidence to the correct package.</p></div></div><div class="table-wrap"><table><thead><tr><th>Reference</th><th>Amount</th><th>Customer</th><th>Status</th><th>Action</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.notification_number||x.id)}</td><td>${money(x.amount)}</td><td>${esc(x.sender_phone)}</td><td>${status(x.status)}</td><td>${(x.status||'').toUpperCase()==='LINKED'?'Linked':`<button class="row-btn" data-link-payment="${x.id}">Link package</button>`}</td></tr>`).join('')}</tbody></table></div></section>`;}
function createEmployee(){const modal=document.createElement('div');modal.style.cssText='position:fixed;inset:0;background:#020a11c9;z-index:30;display:grid;place-items:center;padding:20px';modal.innerHTML=`<div style="position:relative;width:min(480px,100%);background:#0d1e2b;border:1px solid #34536a;border-radius:16px;padding:28px"><button class="modal-close" style="position:absolute;right:15px;top:10px;border:0;background:transparent;color:white;font-size:24px">×</button><p class="eyebrow">DEX LOGISTICS · STAFF ACCESS</p><h2>Add team member</h2><form id="employee-form"><label>Full name<input name="full_name" required></label><label>Email<input name="email" type="email" required></label><label>Temporary password<input name="password" type="password" minlength="8" required></label><label>Company role<select name="role"><option value="sales_rep">Sales representative</option><option value="sales_manager">Sales manager</option><option value="logistics_manager">Logistics manager</option><option value="finance_manager">Finance manager</option><option value="admin">Administrator</option></select></label><button class="primary wide">Create team member</button></form></div>`;document.body.append(modal);modal.querySelector('.modal-close').onclick=()=>modal.remove();modal.querySelector('#employee-form').onsubmit=async e=>{e.preventDefault();const body=Object.fromEntries(new FormData(e.target));try{await adminRequest('/api/public/admin/employees',{method:'POST',body:JSON.stringify({...body,phone:null,commission_percentage:0})});modal.remove();toast('Team member created.');await refreshData()}catch(err){toast(`Create user failed: ${err.message}`,'error')}}}
function render(){if(!state.session)return renderLogin();const view=state.busy?loading():({overview,shipments,payments,staff,commissions,broadcasts,audit})[state.page]();app.innerHTML=shell(view).replaceAll('Shipments','Packages').replaceAll('Shipment control','Package control');bind();}
function packageTable(rows,title){return `<section class="panel"><div class="panel-head"><div><h2>${title}</h2><p>${rows.length} package${rows.length===1?'':'s'}</p></div></div><div class="table-wrap"><table><thead><tr><th>Package image</th><th>Tracking</th><th>Client</th><th>Route / freight</th><th>Amount</th><th>Status</th><th>Actions</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${x.package_photo_url?`<button class="package-thumb" data-photo="${esc(x.package_photo_url)}"><img alt="Package image"><span>View</span></button>`:'<div class="package-thumb empty-thumb">No image</div>'}</td><td><b>${esc(x.id)}</b></td><td>${esc(x.consignee)}<br><small>${esc(x.phone)}</small></td><td>${esc(x.origin)} → ${esc(x.dest)}<br><small>${esc(x.mode||'Freight mode not set')}</small></td><td>${money(x.cost)}</td><td>${status(x.status)}</td><td><button class="row-btn" data-reminder="${x.id}">Copy reminder</button> <button class="row-btn" data-track="${x.id}">Update</button></td></tr>`).join('')||'<tr><td colspan="7" class="muted">No packages in this group.</td></tr>'}</tbody></table></div></section>`;}
function shipments(){const rows=state.data.packages||[], paid=rows.filter(x=>['paid','collected'].includes((x.status||'').toLowerCase())), unpaid=rows.filter(x=>!['paid','collected'].includes((x.status||'').toLowerCase()));return `<section class="toolbar"><div class="search"><span>⌕</span><input id="shipment-search" placeholder="Search package, client or phone"></div></section>${packageTable(unpaid,'Unpaid / awaiting payment packages')}${packageTable(paid,'Paid packages')}`;}
async function loadPackagePhoto(button){try{const path=button.dataset.photo;const response=await fetch(`${state.connection.url}/storage/v1/object/${path.replace(/^\//,'')}`,{headers:{apikey:state.connection.key,Authorization:`Bearer ${state.session.access_token}`}});if(!response.ok)throw new Error();const url=URL.createObjectURL(await response.blob());button.dataset.imageUrl=url;button.querySelector('img').src=url;}catch{button.innerHTML='<span>Photo unavailable</span>';}}
function viewPhoto(path){const source=[...document.querySelectorAll('[data-photo]')].find(x=>x.dataset.photo===path)?.dataset.imageUrl;if(!source)return toast('Package image is loading or unavailable.','error');const modal=document.createElement('div');modal.style.cssText='position:fixed;inset:0;z-index:40;background:#020a11e8;display:grid;place-items:center;padding:30px';modal.innerHTML=`<div style="position:relative;max-width:90vw;max-height:90vh"><button style="position:absolute;right:8px;top:8px;border:0;border-radius:50%;background:#fff;color:#000;width:34px;height:34px;font-size:22px">×</button><img src="${source}" style="display:block;max-width:90vw;max-height:90vh;border-radius:12px"></div>`;document.body.append(modal);modal.querySelector('button').onclick=()=>modal.remove();}
async function copyReminder(id){const pkg=(state.data.packages||[]).find(x=>x.id===id);if(!pkg)return;const message=`Hello ${pkg.consignee||'Customer'}, this is DEX Cargo. This is a reminder that your package (${pkg.id}) is currently in our warehouse in Nairobi. Please come and pick it up. Thank you.`;try{await navigator.clipboard.writeText(message);toast('Customer reminder copied — paste it into WhatsApp.')}catch{toast(message)}}
function bind(){document.querySelectorAll('[data-page],[data-goto]').forEach(b=>b.addEventListener('click',()=>{state.page=b.dataset.page||b.dataset.goto;render()}));$('#refresh')?.addEventListener('click',refreshData);$('#signout')?.addEventListener('click',async()=>{await window.dexAdmin.clearSession();state.session=null;state.data={};renderLogin()});$('#add-staff')?.addEventListener('click',createEmployee);$('#payment-upload')?.addEventListener('submit',e=>{e.preventDefault();uploadPayment(e.target)});document.querySelectorAll('[data-delete-employee]').forEach(b=>b.addEventListener('click',()=>deleteEmployee(b.dataset.deleteEmployee)));document.querySelectorAll('[data-link-payment]').forEach(b=>b.addEventListener('click',()=>linkPayment(b.dataset.linkPayment)));document.querySelectorAll('[data-employee]').forEach(b=>b.addEventListener('click',()=>setEmployee(b.dataset.employee,b.dataset.active!=='true')));document.querySelectorAll('[data-commission]').forEach(b=>b.addEventListener('click',()=>commission(b.dataset.commission,'approve_commission')));document.querySelectorAll('[data-paid]').forEach(b=>b.addEventListener('click',()=>commission(b.dataset.paid,'mark_commission_paid')));document.querySelectorAll('[data-track]').forEach(b=>b.addEventListener('click',()=>openShipment(b.dataset.track)));document.querySelectorAll('[data-photo]').forEach(b=>{loadPackagePhoto(b);b.addEventListener('click',()=>viewPhoto(b.dataset.photo))});document.querySelectorAll('[data-reminder]').forEach(b=>b.addEventListener('click',()=>copyReminder(b.dataset.reminder)));$('#broadcast-form')?.addEventListener('submit',sendBroadcast);$('#export-audit')?.addEventListener('click',exportAudit);}
function staff(){const rows=state.data.employees||[], commissions=state.data.commissions||[], totals=rows.map(e=>({...e,earned:commissions.filter(c=>c.employee_id===e.id||c.employee_id===e.employee_code).reduce((s,c)=>s+Number(c.amount||0),0)})),max=Math.max(1,...totals.map(x=>x.earned));return `<section class="panel"><div class="panel-head"><div><h2>Employee earnings</h2><p>Live commission totals from the backend.</p></div></div>${totals.map(e=>`<div style="display:grid;grid-template-columns:170px 1fr 100px;gap:12px;align-items:center;margin:13px 0"><b>${esc(e.full_name)}</b><div style="height:11px;background:#173044;border-radius:20px;overflow:hidden"><i style="display:block;height:100%;width:${e.earned/max*100}%;background:linear-gradient(90deg,#3ea8fa,#49d4a5)"></i></div><span>${money(e.earned)}</span></div>`).join('')||'<div class="empty">No employee rows returned.</div>'}</section><section class="toolbar"><p class="muted">Manage staff through the secured DEX administrator backend.</p><button class="primary" id="add-staff">+ Add team member</button></section><section class="panel"><div class="table-wrap"><table><thead><tr><th>Employee</th><th>Code</th><th>Role</th><th>Access</th><th></th></tr></thead><tbody>${rows.map(x=>`<tr><td><b>${esc(x.full_name)}</b><br><small>${esc(x.email)}</small></td><td>${esc(x.employee_code)}</td><td>${status(x.role)}</td><td><button class="toggle ${x.is_active?'on':''}" data-employee="${x.id}" data-active="${x.is_active}"><i></i>${x.is_active?'Active':'Inactive'}</button></td><td>${x.role==='admin'?'—':`<button class="row-btn" data-delete-employee="${x.id}">Delete</button>`}</td></tr>`).join('')}</tbody></table></div></section>`;}
async function loadPackagePhoto(button){try{let path=button.dataset.photo;if(/^https?:/i.test(path)){const marker='/object/';path=path.includes(marker)?path.split(marker)[1]:path;}if(!path.startsWith('package-photos/'))path=`package-photos/${path.replace(/^\//,'')}`;const response=await fetch(`${state.connection.url}/storage/v1/object/${path}`,{headers:{apikey:state.connection.key,Authorization:`Bearer ${state.session.access_token}`}});if(!response.ok)throw new Error();const url=URL.createObjectURL(await response.blob());button.dataset.imageUrl=url;button.querySelector('img').src=url;}catch{button.innerHTML='<span>Photo unavailable</span>';}}
function shipmentTable(rows){return packageTable(rows,'Latest packages');}
function payments(){const rows=state.data.notifications||[];return `<section class="panel compose"><div class="panel-head"><div><h2>Upload payment evidence</h2><p>Image evidence may include an optional internal note. Text evidence is a payment message without an image.</p></div></div><form id="payment-upload"><label>Evidence type<select id="evidence-type" name="evidence_type"><option value="IMAGE">Payment screenshot</option><option value="TEXT">Text payment message</option></select></label><label id="image-field">Screenshot<input name="image" type="file" accept="image/*"></label><label id="note-field">Note attached to image (optional)<textarea name="image_note" placeholder="Optional note about this screenshot"></textarea></label><label id="text-field" style="display:none">Payment message<textarea name="text_content" placeholder="Paste the M-Pesa / payment message"></textarea></label><button class="primary" type="submit">Save payment evidence to backend</button></form></section><section class="panel"><div class="panel-head"><div><h2>Payment evidence queue</h2><p>Evidence below is loaded from the shared backend database.</p></div><span class="count">${rows.length} records</span></div><div class="table-wrap"><table><thead><tr><th>Reference</th><th>Evidence</th><th>Note / message</th><th>Status</th><th>Action</th></tr></thead><tbody>${rows.map(x=>`<tr><td><b>${esc(x.notification_number||x.id)}</b></td><td>${esc(x.evidence_type)}</td><td>${esc(x.text_content)}</td><td>${status(x.status)}</td><td>${(x.status||'').toUpperCase()==='LINKED'?'Linked':`<button class="row-btn" data-link-payment="${x.id}">Link package</button>`}</td></tr>`).join('')}</tbody></table></div></section>`;}
async function uploadPayment(form){const f=new FormData(form),type=f.get('evidence_type'),file=f.get('image');if(type==='IMAGE'&&(!file||!file.size))return toast('Choose a payment screenshot.','error');if(type==='TEXT'&&!String(f.get('text_content')||'').trim())return toast('Enter the payment message.','error');try{let image_url=null;let text_content=type==='IMAGE'?String(f.get('image_note')||'').trim()||null:String(f.get('text_content')||'').trim();if(type==='IMAGE'){const filename=`proof_${Date.now()}_${file.name.replace(/[^a-zA-Z0-9._-]/g,'_')}`;const upload=await fetch(`${state.connection.url}/storage/v1/object/proofs/${filename}`,{method:'POST',headers:{apikey:state.connection.key,Authorization:`Bearer ${state.session.access_token}`,'Content-Type':file.type||'image/jpeg','x-upsert':'false'},body:file});if(!upload.ok)throw new Error(`Image upload failed: ${await upload.text()}`);image_url=`proofs/${filename}`;}const now=new Date().toISOString(),id=`PN-${Date.now()}`,notification_number=`PAY-${now.slice(0,10).replaceAll('-','')}-${Date.now().toString().slice(-5)}`;const inserted=await request('rest/v1/payment_notifications',{method:'POST',headers:{Prefer:'return=representation'},body:JSON.stringify({id,notification_number,evidence_type:type,image_url,text_content,uploaded_by:state.profile?.name||state.session?.user?.email||'Admin',uploaded_at:now,status:'PENDING',timestamp:now})});if(!Array.isArray(inserted)||!inserted.length)throw new Error('Backend did not confirm the payment record.');try{await request('rest/v1/audit_logs',{method:'POST',headers:{Prefer:'return=representation'},body:JSON.stringify({id:`AL-${Date.now()}`,action:'UPLOAD_PAYMENT_EVIDENCE',actor:state.profile?.name||'Admin',timestamp:now,details:`Uploaded ${type} payment evidence: ${notification_number}`})})}catch{}toast('Payment evidence saved to the shared backend.');form.reset();await refreshData()}catch(e){toast(`Payment was not saved: ${e.message}`,'error')}}
function bind(){document.querySelectorAll('[data-page],[data-goto]').forEach(b=>b.addEventListener('click',()=>{state.page=b.dataset.page||b.dataset.goto;render()}));$('#refresh')?.addEventListener('click',refreshData);$('#signout')?.addEventListener('click',async()=>{await window.dexAdmin.clearSession();state.session=null;state.data={};renderLogin()});$('#add-staff')?.addEventListener('click',createEmployee);$('#payment-upload')?.addEventListener('submit',e=>{e.preventDefault();uploadPayment(e.target)});$('#evidence-type')?.addEventListener('change',e=>{const image=e.target.value==='IMAGE';$('#image-field').style.display=image?'':'none';$('#note-field').style.display=image?'':'none';$('#text-field').style.display=image?'none':''});document.querySelectorAll('[data-delete-employee]').forEach(b=>b.addEventListener('click',()=>deleteEmployee(b.dataset.deleteEmployee)));document.querySelectorAll('[data-link-payment]').forEach(b=>b.addEventListener('click',()=>linkPayment(b.dataset.linkPayment)));document.querySelectorAll('[data-employee]').forEach(b=>b.addEventListener('click',()=>setEmployee(b.dataset.employee,b.dataset.active!=='true')));document.querySelectorAll('[data-commission]').forEach(b=>b.addEventListener('click',()=>commission(b.dataset.commission,'approve_commission')));document.querySelectorAll('[data-paid]').forEach(b=>b.addEventListener('click',()=>commission(b.dataset.paid,'mark_commission_paid')));document.querySelectorAll('[data-track]').forEach(b=>b.addEventListener('click',()=>openShipment(b.dataset.track)));document.querySelectorAll('[data-photo]').forEach(b=>{loadPackagePhoto(b);b.addEventListener('click',()=>viewPhoto(b.dataset.photo))});document.querySelectorAll('[data-reminder]').forEach(b=>b.addEventListener('click',()=>copyReminder(b.dataset.reminder)));$('#broadcast-form')?.addEventListener('submit',sendBroadcast);$('#export-audit')?.addEventListener('click',exportAudit);}
function payments(){const rows=state.data.notifications||[];return `<section class="panel compose"><div class="panel-head"><div><h2>Upload payment evidence</h2><p>Image evidence may include an optional internal note. Text evidence is a payment message without an image.</p></div></div><form id="payment-upload"><label>Evidence type<select id="evidence-type" name="evidence_type"><option value="IMAGE">Payment screenshot</option><option value="TEXT">Text payment message</option></select></label><label id="image-field">Screenshot<input name="image" type="file" accept="image/*"></label><label id="note-field">Note attached to image (optional)<textarea name="image_note" placeholder="Optional note about this screenshot"></textarea></label><label id="text-field" style="display:none">Payment message<textarea name="text_content" placeholder="Paste the M-Pesa / payment message"></textarea></label><button class="primary" type="submit">Save payment evidence to backend</button></form></section><section class="panel"><div class="panel-head"><div><h2>Payment evidence queue</h2><p>Open screenshots or read the complete payment message before linking it.</p></div><span class="count">${rows.length} records</span></div><div class="table-wrap"><table><thead><tr><th>Reference</th><th>Evidence</th><th>Details</th><th>Status</th><th>Action</th></tr></thead><tbody>${rows.map(x=>`<tr><td><b>${esc(x.notification_number||x.id)}</b></td><td>${x.image_url?`<button class="evidence-preview" data-evidence-image="${esc(x.image_url)}" title="Open payment screenshot"><img data-evidence-thumb="${esc(x.image_url)}" alt="Payment evidence"><span>View image</span></button>`:`<button class="row-btn" data-evidence-text="${esc(x.text_content||'No payment message was attached.')}">View text</button>`}</td><td><div class="evidence-note">${esc(x.text_content||'No note attached')}</div></td><td>${status(x.status)}</td><td>${(x.status||'').toUpperCase()==='LINKED'?'Linked':`<button class="row-btn" data-link-payment="${x.id}">Link package</button>`}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">No payment evidence has been uploaded yet.</td></tr>'}</tbody></table></div></section>`;}
async function viewEvidenceImage(rawPath){try{let path=rawPath;if(/^https?:/i.test(path)){const marker='/object/';path=path.includes(marker)?path.split(marker)[1]:path;}if(!path.startsWith('proofs/'))path=`proofs/${path.replace(/^\//,'')}`;const response=await fetch(`${state.connection.url}/storage/v1/object/${path}`,{headers:{apikey:state.connection.key,Authorization:`Bearer ${state.session.access_token}`}});if(!response.ok)throw new Error(await response.text());const url=URL.createObjectURL(await response.blob());const modal=document.createElement('div');modal.style.cssText='position:fixed;inset:0;z-index:50;background:#020a11e8;display:grid;place-items:center;padding:30px';modal.innerHTML=`<div style="position:relative;max-width:90vw;max-height:90vh"><button style="position:absolute;right:8px;top:8px;border:0;border-radius:50%;background:#fff;color:#000;width:34px;height:34px;font-size:22px">×</button><img src="${url}" style="display:block;max-width:90vw;max-height:90vh;border-radius:12px"></div>`;document.body.append(modal);modal.querySelector('button').onclick=()=>{URL.revokeObjectURL(url);modal.remove()}}catch(e){toast(`Evidence image unavailable: ${e.message}`,'error')}}
async function loadEvidenceThumbnail(image){try{let path=image.dataset.evidenceThumb;if(/^https?:/i.test(path)){const marker='/object/';path=path.includes(marker)?path.split(marker)[1]:path;}if(!path.startsWith('proofs/'))path=`proofs/${path.replace(/^\//,'')}`;const response=await fetch(`${state.connection.url}/storage/v1/object/${path}`,{headers:{apikey:state.connection.key,Authorization:`Bearer ${state.session.access_token}`}});if(!response.ok)throw new Error();image.src=URL.createObjectURL(await response.blob())}catch{image.closest('.evidence-preview')?.classList.add('unavailable')}}
function viewEvidenceText(message){const modal=document.createElement('div');modal.style.cssText='position:fixed;inset:0;z-index:50;background:#020a11e8;display:grid;place-items:center;padding:30px';modal.innerHTML=`<div style="position:relative;width:min(620px,92vw);max-height:80vh;overflow:auto;background:#fff;color:#17243a;border-radius:14px;padding:30px"><button style="position:absolute;right:10px;top:10px;border:0;border-radius:50%;background:#17243a;color:#fff;width:34px;height:34px;font-size:22px">×</button><h2 style="margin-top:0">Payment message</h2><div style="white-space:pre-wrap;line-height:1.65">${esc(message)}</div></div>`;document.body.append(modal);modal.querySelector('button').onclick=()=>modal.remove()}
function bind(){document.querySelectorAll('[data-page],[data-goto]').forEach(b=>b.addEventListener('click',()=>{state.page=b.dataset.page||b.dataset.goto;render()}));$('#refresh')?.addEventListener('click',refreshData);$('#signout')?.addEventListener('click',async()=>{await window.dexAdmin.clearSession();state.session=null;state.data={};renderLogin()});$('#add-staff')?.addEventListener('click',createEmployee);$('#payment-upload')?.addEventListener('submit',e=>{e.preventDefault();uploadPayment(e.target)});$('#evidence-type')?.addEventListener('change',e=>{const image=e.target.value==='IMAGE';$('#image-field').style.display=image?'':'none';$('#note-field').style.display=image?'':'none';$('#text-field').style.display=image?'none':''});document.querySelectorAll('[data-evidence-image]').forEach(b=>b.addEventListener('click',()=>viewEvidenceImage(b.dataset.evidenceImage)));document.querySelectorAll('[data-evidence-thumb]').forEach(loadEvidenceThumbnail);document.querySelectorAll('[data-evidence-text]').forEach(b=>b.addEventListener('click',()=>viewEvidenceText(b.dataset.evidenceText)));document.querySelectorAll('[data-delete-employee]').forEach(b=>b.addEventListener('click',()=>deleteEmployee(b.dataset.deleteEmployee)));document.querySelectorAll('[data-link-payment]').forEach(b=>b.addEventListener('click',()=>linkPayment(b.dataset.linkPayment)));document.querySelectorAll('[data-employee]').forEach(b=>b.addEventListener('click',()=>setEmployee(b.dataset.employee,b.dataset.active!=='true')));document.querySelectorAll('[data-commission]').forEach(b=>b.addEventListener('click',()=>commission(b.dataset.commission,'approve_commission')));document.querySelectorAll('[data-paid]').forEach(b=>b.addEventListener('click',()=>commission(b.dataset.paid,'mark_commission_paid')));document.querySelectorAll('[data-track]').forEach(b=>b.addEventListener('click',()=>openShipment(b.dataset.track)));document.querySelectorAll('[data-photo]').forEach(b=>{loadPackagePhoto(b);b.addEventListener('click',()=>viewPhoto(b.dataset.photo))});document.querySelectorAll('[data-reminder]').forEach(b=>b.addEventListener('click',()=>copyReminder(b.dataset.reminder)));$('#broadcast-form')?.addEventListener('submit',sendBroadcast);$('#export-audit')?.addEventListener('click',exportAudit);}
// Final money-flow parity with Android: the backend owns the clearing, revenue and commission rules.
async function refreshData(){state.busy=true;render();const get=async p=>{try{return await request(p)}catch(e){console.warn(e);return[]}};const[packages,notifications,commissions,audits,broadcasts,employees,revenue]=await Promise.all([get('rest/v1/cargo_packages?select=*&order=registered_at.desc&limit=500'),get('rest/v1/payment_notifications?select=*&order=uploaded_at.desc&limit=200'),get('rest/v1/commissions?select=*&order=created_at.desc&limit=300'),get('rest/v1/audit_logs?select=*&order=timestamp.desc&limit=150'),get('rest/v1/broadcast_messages?select=*&order=timestamp.desc&limit=50'),adminRequest('/api/public/admin/employees').then(x=>x.employees||[]).catch(()=>get('rest/v1/employees?select=*&order=full_name.asc')),adminRequest('/api/public/revenue-summary').catch(e=>{console.warn('Revenue summary unavailable',e);return null})]);state.data={packages,notifications,commissions,audits,broadcasts,employees,revenue};state.busy=false;render()}
async function linkPayment(id){const pkgId=prompt('Enter the package tracking number to clear');if(!pkgId)return;const pkg=(state.data.packages||[]).find(x=>String(x.id).toLowerCase()===pkgId.trim().toLowerCase());if(!pkg)return toast('That package was not found in the live backend list. Refresh and try again.','error');try{const result=await adminRequest('/api/public/link-payment',{method:'POST',body:JSON.stringify({payment_notification_id:id,allocations:[{package_id:pkg.id,amount:Number(pkg.cost||0)}]})});if(result&&result.ok===false)throw new Error(result.error||'The backend did not confirm the payment link.');toast(`Payment linked. ${pkg.id} is now cleared and included in company revenue.`);await refreshData()}catch(e){toast(`Payment link failed: ${e.message}`,'error')}}
// Mobile parity: operational treasury and backend-driven commission ledger.
// These are read directly from the same cargo, payment and commissions tables used by the Android app.
function overview(){const p=state.data.packages||[],n=state.data.notifications||[],staff=state.data.employees||[],summary=state.data.revenue||{};const cleared=p.filter(x=>['cleared','collected','released'].includes((x.status||'').toLowerCase())),unpaid=p.filter(x=>['registered','awaiting_payment','received'].includes((x.status||'').toLowerCase())),pendingEvidence=n.filter(x=>(x.status||'').toUpperCase()==='PENDING').length,clients=new Set(p.map(x=>x.phone).filter(Boolean)).size;const gross=Number(summary.gross_income??summary.revenue?.gross_income??summary.revenue?.grossIncome??summary.revenue?.total??cleared.reduce((s,x)=>s+Number(x.cost||0),0)),totalRevenue=Number(summary.revenue?.total??summary.gross_income??gross),pendingValue=Number(summary.pending_release?.value??summary.packages?.pending_release_value??summary.packages?.outstanding_value??unpaid.reduce((s,x)=>s+Number(x.cost||0),0)),net=Number(summary.net_retained??gross),max=Math.max(1,unpaid.length,cleared.length);return `<section class="metrics">${metric('Packages registered',p.length,'Accurate live package count','blue')}${metric('Pending payments',pendingEvidence,`${unpaid.length} package${unpaid.length===1?'':'s'} still unpaid / pending release`,'red')}${metric('Total company revenue',money(totalRevenue),'Cleared package value only','amber')}${metric('Gross income',money(gross),`${cleared.length} cleared or released package${cleared.length===1?'':'s'}`,'green')}</section><section class="grid two"><article class="panel"><div class="panel-head"><div><h2>Package money flow</h2><p>Cleared packages add to revenue; registered packages remain pending.</p></div></div><div class="flow">${[['still unpaid',unpaid.length],['cleared / released',cleared.length]].map(([name,count])=>`<div><b>${count}</b><span>${name}</span><i style="width:${Math.max(8,count/max*100)}%"></i></div>`).join('')}</div></article><article class="panel treasury"><div class="panel-head"><div><h2>Company treasury</h2><p>Values returned by the shared revenue-summary backend.</p></div><button class="text-btn" data-goto="commissions">Open ledger →</button></div><div class="treasury-grid"><div><small>Total revenue</small><b>${money(totalRevenue)}</b></div><div><small>Gross income</small><b>${money(gross)}</b></div><div><small>Net retained</small><b>${money(net)}</b></div><div><small>Still unpaid / pending release</small><b>${money(pendingValue)}</b></div></div></article></section><section class="grid two"><article class="panel attention"><div class="panel-head"><div><h2>Action center</h2><p>Items requiring administrator attention</p></div></div><button class="action" data-goto="payments"><span>◉</span><div><b>${pendingEvidence} payment evidence item${pendingEvidence===1?'':'s'} awaiting package link</b><small>Linking it clears the package and records its revenue.</small></div>›</button><button class="action" data-goto="shipments"><span>◈</span><div><b>${unpaid.length} package${unpaid.length===1?'':'s'} still unpaid / pending release</b><small>Review registered package value.</small></div>›</button></article><article class="panel"><div class="panel-head"><div><h2>Workforce snapshot</h2><p>Administrators do not earn commission.</p></div><button class="text-btn" data-goto="staff">Open staff →</button></div>${staff.length?staff.filter(e=>(e.role||'').toLowerCase()!=='admin').slice(0,5).map(e=>`<div class="action"><span>◉</span><div><b>${esc(e.full_name||e.email)}</b><small>${esc(e.role||'Employee')} · ${e.is_active?'Active':'Inactive'}</small></div></div>`).join(''):'<div class="empty">No employee rows returned from the backend.</div>'}</article></section><section class="panel"><div class="panel-head"><div><h2>Latest packages</h2><p>Photo, freight mode, status and customer reminder actions.</p></div><button class="text-btn" data-goto="shipments">View all →</button></div>${shipmentTable(p.slice(0,10))}</section>`;}
function commissions(){const staff=(state.data.employees||[]).filter(e=>(e.role||'').toLowerCase()!=='admin'),allowed=new Set(staff.flatMap(e=>[e.id,e.employee_code]).filter(Boolean)),rows=(state.data.commissions||[]).filter(x=>!allowed.size||allowed.has(x.employee_id)),paid=rows.filter(x=>['paid','settled'].includes((x.status||'').toLowerCase())),approved=rows.filter(x=>(x.status||'').toLowerCase()==='approved'),pending=rows.filter(x=>(x.status||'').toLowerCase()==='pending'),sum=a=>a.reduce((s,x)=>s+Number(x.amount||0),0),byEmployee=staff.map(e=>{const own=rows.filter(x=>x.employee_id===e.id||x.employee_id===e.employee_code);return {...e,total:sum(own),due:sum(own.filter(x=>!['paid','settled'].includes((x.status||'').toLowerCase())))};});return `<section class="metrics commission-metrics">${metric('Commission records',rows.length,'Admin roles are excluded','blue')}${metric('Awaiting approval',money(sum(pending)),`${pending.length} record${pending.length===1?'':'s'}`,'amber')}${metric('Approved to pay',money(sum(approved)),`${approved.length} record${approved.length===1?'':'s'}`,'red')}${metric('Paid to staff',money(sum(paid)),`${paid.length} record${paid.length===1?'':'s'}`,'green')}</section><section class="panel"><div class="panel-head"><div><h2>Employee commission accumulation</h2><p>Eligible roles only: sales rep, sales manager and logistics manager.</p></div></div><div class="table-wrap"><table><thead><tr><th>Employee</th><th>Role</th><th>Accumulated</th><th>Outstanding</th></tr></thead><tbody>${byEmployee.map(e=>`<tr><td><b>${esc(e.full_name||e.email)}</b><br><small>${esc(e.employee_code||e.id)}</small></td><td>${status(e.role||'employee')}</td><td>${money(e.total)}</td><td>${money(e.due)}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">No eligible employee records returned.</td></tr>'}</tbody></table></div></section><section class="panel"><div class="panel-head"><div><h2>Commission payment ledger</h2><p>Automatically awarded for paid or cleared packages; administrators are excluded.</p></div><span class="count">${money(sum(rows.filter(x=>!['paid','settled'].includes((x.status||'').toLowerCase()))))} outstanding</span></div>${rows.length?`<div class="table-wrap"><table><thead><tr><th>Package / reference</th><th>Employee</th><th>Type</th><th>Amount</th><th>Status</th><th>Action</th></tr></thead><tbody>${rows.map(c=>{const stateName=(c.status||'').toLowerCase();return `<tr><td><b>${esc(c.reference||c.order_id||c.package_id||'—')}</b></td><td>${esc(c.employee_id)}</td><td>${status(c.commission_type||c.type||'package payment')}</td><td>${money(c.amount)}</td><td>${status(c.status)}</td><td>${stateName==='pending'?`<button class="row-btn approve" data-commission="${c.id}">Approve</button>`:stateName==='approved'?`<button class="row-btn paid" data-paid="${c.id}">Mark paid</button>`:'—'}</td></tr>`}).join('')}</tbody></table></div>`:'<div class="empty">No eligible commission rows exist yet.</div>'}</section>`;}
// Package actions use the backend status vocabulary: registered -> paid -> cleared -> collected.
// A collected/released package is never allowed to move backwards from this console.
async function openShipment(id){const pkg=(state.data.packages||[]).find(x=>x.id===id);if(!pkg)return toast('Package was not found. Refresh and try again.','error');const current=(pkg.status||'registered').toLowerCase();const choice=prompt(`Update ${id}\n\n1 = Registered (unpaid)\n2 = Paid\n3 = Cleared (payment received / ready for release)\n4 = Collected (released to client)\n\nCurrent status: ${current}`,'3');if(choice===null)return;const selected={1:'registered',2:'paid',3:'cleared',4:'collected',registered:'registered',paid:'paid',cleared:'cleared',collected:'collected'}[String(choice).trim().toLowerCase()];if(!selected)return toast('Choose Registered, Paid, Cleared or Collected.','error');if(['collected','released'].includes(current)&&selected!==current)return toast('A collected package cannot be downgraded.','error');const now=new Date().toISOString(),patch={status:selected};if(['paid','cleared'].includes(selected))patch.paid_at=pkg.paid_at||now;if(selected==='cleared')patch.cleared_at=pkg.cleared_at||now;if(selected==='collected')patch.collected_at=pkg.collected_at||now;try{await request(`rest/v1/cargo_packages?id=eq.${encodeURIComponent(id)}`,{method:'PATCH',headers:{Prefer:'return=representation'},body:JSON.stringify(patch)});toast(`Package ${id} updated to ${selected}.`);await refreshData()}catch(e){toast(`Package update failed: ${e.message}`,'error')}}
async function copyReminder(id){const pkg=(state.data.packages||[]).find(x=>x.id===id);if(!pkg)return;const language=prompt('Choose reminder language:\n1 = English\n2 = Chinese','1');if(language===null)return;const name=pkg.consignee||'Customer',tracking=pkg.id;const english=`Hello ${name}, this is DEX Cargo. This is a reminder that your package (${tracking}) is currently in our Nairobi warehouse. Please come and pick it up. Thank you.`;const chinese=`您好，${name}。这里是 DEX Cargo。提醒您：您的包裹（${tracking}）目前在我们内罗毕的仓库。请您前来领取。谢谢。`;const message=['2','zh','chinese'].includes(String(language).trim().toLowerCase())?chinese:english;try{await navigator.clipboard.writeText(message);toast('Customer reminder copied to clipboard.')}catch{toast(message)}}
function shipments(){const rows=state.data.packages||[],pending=rows.filter(x=>['registered','awaiting_payment','received'].includes((x.status||'').toLowerCase())),settled=rows.filter(x=>!['registered','awaiting_payment','received'].includes((x.status||'').toLowerCase()));return `<section class="toolbar"><div class="search"><span>⌕</span><input id="shipment-search" placeholder="Search package, client or phone"></div></section>${packageTable(pending,'Still unpaid / pending release')}${packageTable(settled,'Paid, cleared and collected packages')}`}
function commissions(){const staff=(state.data.employees||[]).filter(e=>(e.role||'').toLowerCase()!=='admin'),allowed=new Set(staff.flatMap(e=>[e.id,e.employee_code]).filter(Boolean)),rows=(state.data.commissions||[]).filter(x=>!allowed.size||allowed.has(x.employee_id)),paid=rows.filter(x=>['paid','settled'].includes((x.status||'').toLowerCase())),approved=rows.filter(x=>(x.status||'').toLowerCase()==='approved'),pending=rows.filter(x=>(x.status||'').toLowerCase()==='pending'),sum=a=>a.reduce((s,x)=>s+Number(x.amount||0),0),byEmployee=staff.map(e=>{const own=rows.filter(x=>x.employee_id===e.id||x.employee_id===e.employee_code);return {...e,total:sum(own),due:sum(own.filter(x=>!['paid','settled'].includes((x.status||'').toLowerCase())))};});return `<section class="metrics commission-metrics">${metric('Commission records',rows.length,'Admin roles are excluded','blue')}${metric('Awaiting approval',money(sum(pending)),`${pending.length} record${pending.length===1?'':'s'}`,'amber')}${metric('Approved to pay',money(sum(approved)),`${approved.length} record${approved.length===1?'':'s'}`,'red')}${metric('Paid to staff',money(sum(paid)),`${paid.length} record${paid.length===1?'':'s'}`,'green')}</section><section class="panel"><div class="panel-head"><div><h2>Employee commission accumulation</h2><p>Eligible roles only: sales rep, sales manager and logistics manager.</p></div></div><div class="table-wrap"><table><thead><tr><th>Employee</th><th>Role</th><th>Accumulated</th><th>Outstanding</th></tr></thead><tbody>${byEmployee.map(e=>`<tr><td><b>${esc(e.full_name||e.email)}</b><br><small>${esc(e.employee_code||e.id)}</small></td><td>${status(e.role||'employee')}</td><td>${money(e.total)}</td><td>${money(e.due)}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">No commission yet</td></tr>'}</tbody></table></div></section><section class="panel"><div class="panel-head"><div><h2>Commission payment ledger</h2><p>Automatically awarded for paid or cleared packages; administrators are excluded.</p></div><span class="count">${money(sum(rows.filter(x=>!['paid','settled'].includes((x.status||'').toLowerCase()))))} outstanding</span></div>${rows.length?`<div class="table-wrap"><table><thead><tr><th>Package / reference</th><th>Employee</th><th>Type</th><th>Amount</th><th>Status</th><th>Action</th></tr></thead><tbody>${rows.map(c=>{const stateName=(c.status||'').toLowerCase();return `<tr><td><b>${esc(c.reference||c.order_id||c.package_id||'—')}</b></td><td>${esc(c.employee_id)}</td><td>${status(c.commission_type||c.type||'package payment')}</td><td>${money(c.amount)}</td><td>${status(c.status)}</td><td>${stateName==='pending'?`<button class="row-btn approve" data-commission="${c.id}">Approve</button>`:stateName==='approved'?`<button class="row-btn paid" data-paid="${c.id}">Mark paid</button>`:'—'}</td></tr>`}).join('')}</tbody></table></div>`:'<div class="empty">No commission yet</div>'}</section>`;}
function packageDialog(content){const modal=document.createElement('div');modal.className='package-dialog-backdrop';modal.innerHTML=`<div class="package-dialog">${content}<button class="dialog-close" aria-label="Close">×</button></div>`;document.body.append(modal);modal.querySelector('.dialog-close').onclick=()=>modal.remove();modal.addEventListener('click',e=>{if(e.target===modal)modal.remove()});return modal}
async function copyText(text){try{await navigator.clipboard.writeText(text);return true}catch{const area=document.createElement('textarea');area.value=text;area.style.cssText='position:fixed;opacity:0';document.body.append(area);area.select();const ok=document.execCommand('copy');area.remove();return ok}}
function copyReminder(id){const pkg=(state.data.packages||[]).find(x=>String(x.id)===String(id));if(!pkg)return toast('Package was not found. Refresh and try again.','error');const name=pkg.consignee||'Customer',tracking=pkg.id;const english=`Hello ${name}, this is DEX Cargo. This is a reminder that your package (${tracking}) is currently in our Nairobi warehouse. Please come and pick it up. Thank you.`;const chinese=`您好，${name}。这里是 DEX Cargo。提醒您：您的包裹（${tracking}）目前在我们内罗毕的仓库。请您前来领取。谢谢。`;const modal=packageDialog(`<p class="eyebrow">DEX LOGISTICS · CLIENT REMINDER</p><h2>Copy package reminder</h2><p>Choose the message language for ${esc(name)}.</p><div class="dialog-actions"><button class="primary" data-copy-language="en">Copy English</button><button class="secondary" data-copy-language="zh">复制中文</button></div>`);modal.querySelectorAll('[data-copy-language]').forEach(button=>button.onclick=async()=>{const ok=await copyText(button.dataset.copyLanguage==='zh'?chinese:english);toast(ok?'Customer reminder copied to clipboard.':'Could not copy automatically; please try again.','error');if(ok)modal.remove()})}
function openShipment(id){const pkg=(state.data.packages||[]).find(x=>String(x.id)===String(id));if(!pkg)return toast('Package was not found. Refresh and try again.','error');const current=(pkg.status||'registered').toLowerCase(),locked=['collected','released'].includes(current);const modal=packageDialog(`<p class="eyebrow">DEX LOGISTICS · PACKAGE STATUS</p><h2>Update ${esc(pkg.id)}</h2><p>Current status: <b>${esc(current)}</b>${locked?' — collected packages cannot be moved backwards.':''}</p><div class="status-actions">${[['registered','Registered · unpaid'],['paid','Paid'],['cleared','Cleared · ready for release'],['collected','Collected · released to client']].map(([value,label])=>`<button class="row-btn ${value===current?'selected-status':''}" data-package-status="${value}" ${locked&&value!==current?'disabled':''}>${label}</button>`).join('')}</div>`);modal.querySelectorAll('[data-package-status]').forEach(button=>button.onclick=async()=>{const selected=button.dataset.packageStatus;if(locked&&selected!==current)return;const now=new Date().toISOString(),patch={status:selected};if(['paid','cleared'].includes(selected))patch.paid_at=pkg.paid_at||now;if(selected==='cleared')patch.cleared_at=pkg.cleared_at||now;if(selected==='collected')patch.collected_at=pkg.collected_at||now;try{button.disabled=true;await request(`rest/v1/cargo_packages?id=eq.${encodeURIComponent(pkg.id)}`,{method:'PATCH',headers:{Prefer:'return=representation'},body:JSON.stringify(patch)});modal.remove();toast(`Package ${pkg.id} updated to ${selected}.`);await refreshData()}catch(e){button.disabled=false;toast(`Package update failed: ${e.message}`,'error')}})}
function bind(){document.querySelectorAll('[data-page],[data-goto]').forEach(b=>b.addEventListener('click',()=>{state.page=b.dataset.page||b.dataset.goto;render()}));$('#refresh')?.addEventListener('click',refreshData);$('#signout')?.addEventListener('click',async()=>{await window.dexAdmin.clearSession();state.session=null;state.data={};renderLogin()});$('#add-staff')?.addEventListener('click',createEmployee);$('#payment-upload')?.addEventListener('submit',e=>{e.preventDefault();uploadPayment(e.target)});$('#evidence-type')?.addEventListener('change',e=>{const image=e.target.value==='IMAGE';$('#image-field').style.display=image?'':'none';$('#note-field').style.display=image?'':'none';$('#text-field').style.display=image?'none':''});document.querySelectorAll('[data-evidence-image]').forEach(b=>b.addEventListener('click',()=>viewEvidenceImage(b.dataset.evidenceImage)));document.querySelectorAll('[data-evidence-thumb]').forEach(loadEvidenceThumbnail);document.querySelectorAll('[data-evidence-text]').forEach(b=>b.addEventListener('click',()=>viewEvidenceText(b.dataset.evidenceText)));document.querySelectorAll('[data-delete-employee]').forEach(b=>b.addEventListener('click',()=>deleteEmployee(b.dataset.deleteEmployee)));document.querySelectorAll('[data-link-payment]').forEach(b=>b.addEventListener('click',()=>linkPayment(b.dataset.linkPayment)));document.querySelectorAll('[data-employee]').forEach(b=>b.addEventListener('click',()=>setEmployee(b.dataset.employee,b.dataset.active!=='true')));document.querySelectorAll('[data-commission]').forEach(b=>b.addEventListener('click',()=>commission(b.dataset.commission,'approve_commission')));document.querySelectorAll('[data-paid]').forEach(b=>b.addEventListener('click',()=>commission(b.dataset.paid,'mark_commission_paid')));document.querySelectorAll('[data-track]').forEach(b=>b.addEventListener('click',()=>openShipment(b.dataset.track)));document.querySelectorAll('[data-reminder]').forEach(b=>b.addEventListener('click',()=>copyReminder(b.dataset.reminder)));document.querySelectorAll('[data-photo]').forEach(b=>{loadPackagePhoto(b);b.addEventListener('click',()=>viewPhoto(b.dataset.photo))});$('#broadcast-form')?.addEventListener('submit',sendBroadcast);$('#export-audit')?.addEventListener('click',exportAudit)}

/* Department workspaces. These declarations deliberately sit last: this project
   keeps earlier compatibility implementations in the same renderer file. */
function normalizeRole(value){const r=String(value||'').toLowerCase().trim().replace(/[ -]/g,'_');return ({admin:'admin',administrator:'admin',sales_rep:'sales_rep',sales_representative:'sales_rep',salesrepresentative:'sales_rep',sr:'sales_rep',sales_manager:'sales_manager',salesmanager:'sales_manager',sm:'sales_manager',logistics_manager:'logistics_manager',logisticsmanager:'logistics_manager',lm:'logistics_manager',logistics:'logistics_manager',finance_manager:'finance_manager',financemanager:'finance_manager',finance:'finance_manager',fm:'finance_manager'})[r]||r}
function roleLabel(role){return ({admin:'Administrator',sales_rep:'Sales Representative',sales_manager:'Sales Manager',logistics_manager:'Logistics Manager',finance_manager:'Finance Manager'})[role]||'Team member'}
async function hydrateIdentity(){const uid=state.session.user.id;const [profiles,roles]=await Promise.all([request(`rest/v1/profiles?id=eq.${encodeURIComponent(uid)}&select=*`).catch(()=>[]),request(`rest/v1/user_roles?user_id=eq.${encodeURIComponent(uid)}&select=*`).catch(()=>[])]);state.profile=profiles?.[0]||{email:state.session.user.email,full_name:state.session.user.email};state.role=normalizeRole(roles?.[0]?.role||state.profile?.role);if(!state.role)throw new Error('No dashboard role is assigned to this account. Ask an administrator to assign a company role.');state.page='overview'}
function navItems(role){const admin=[['overview','Overview','◫'],['shipments','Packages','▣'],['payments','Payments','◉'],['staff','Staff','♙'],['commissions','Commissions','◈'],['announcements','Announcements','◌'],['audit','Audit log','◷']];const salesRep=[['overview','My overview','◫'],['my_packages','My packages','▣'],['reminders','Client reminders','◌'],['my_commissions','My commissions','◈'],['announcements','Announcements','◌']];const salesManager=[['overview','Sales overview','◫'],['sales_packages','Sales packages','▣'],['team_performance','Team performance','◈'],['commissions','Team commissions','◈'],['announcements','Announcements','◌']];const logistics=[['overview','Warehouse overview','◫'],['warehouse_packages','Warehouse packages','▣'],['payments','Payment evidence','◉'],['release_queue','Release queue','✓'],['announcements','Announcements','◌']];const finance=[['overview','Finance overview','◫'],['finance_invoices','Invoices & billing','▣'],['payments','Payment evidence','◉'],['finance_receivables','Receivables','◈'],['finance_expenses','Expenses','◌'],['finance_payables','Payables','◌'],['finance_profitability','Package profitability','◫'],['finance_tax','KRA & tax','✓'],['finance_reports','Reports','◷']];return role==='admin'?admin:role==='sales_rep'?salesRep:role==='sales_manager'?salesManager:role==='logistics_manager'?logistics:finance}
function shell(content){const role=state.role||'admin',name=state.profile?.full_name||state.profile?.name||state.session?.user?.email||'DEX team';return `<div class="app-shell role-${esc(role)}"><aside class="sidebar"><div class="brand"><img src="assets/dex-logo.png" onerror="this.style.display='none'"><div><b>DEX</b><span>logistics</span></div></div><div class="role-chip">${esc(roleLabel(role))}</div><nav>${navItems(role).map(([id,label,icon])=>`<button class="nav-item ${state.page===id?'active':''}" data-page="${id}"><i>${icon}</i>${label}</button>`).join('')}</nav><div class="sidebar-bottom"><button class="nav-item" id="signout"><i>↪</i>Sign out</button></div></aside><main><header class="topbar"><div><p class="eyebrow">DEX LOGISTICS · ${esc(roleLabel(role)).toUpperCase()}</p><h1>${esc(pageTitle())}</h1></div><div class="top-actions"><button class="refresh-btn" id="refresh">↻ Refresh data</button><div class="user"><span>${esc(String(name).slice(0,1).toUpperCase())}</span><div><b>${esc(name)}</b><small>${esc(roleLabel(role))}</small></div></div></div></header><div id="toast"></div><div class="content">${content}</div></main></div>`}
function pageTitle(){const labels={overview:'Overview',my_packages:'My packages',reminders:'Client reminders',my_commissions:'My commissions',sales_packages:'Sales packages',team_performance:'Team performance',warehouse_packages:'Warehouse packages',release_queue:'Release queue',finance_invoices:'Invoices & billing',finance_receivables:'Receivables',finance_expenses:'Expenses',finance_payables:'Payables',finance_profitability:'Package profitability',finance_tax:'KRA & tax',finance_reports:'Reports',shipments:'Packages',payments:'Payments',staff:'Staff',commissions:'Commissions',announcements:'Announcements',audit:'Audit log'};return labels[state.page]||'DEX Admin'}
function packageValue(p){return Number(p.cost??p.price??p.amount??p.total??0)||0}
function clearedPackage(p){return ['cleared','collected','released'].includes(String(p.status||'').toLowerCase())}
function pendingPackage(p){return ['registered','awaiting_payment','received','paid'].includes(String(p.status||'').toLowerCase())}
function myPackages(){const rows=state.data.packages||[],me=[state.profile?.id,state.session?.user?.id,state.profile?.email,state.session?.user?.email,state.profile?.full_name,state.profile?.name].filter(Boolean).map(x=>String(x).toLowerCase());return rows.filter(p=>['sales_rep','sales_rep_id','sales_rep_email','employee_id','registered_by','assigned_to','created_by'].some(key=>me.includes(String(p[key]||'').toLowerCase())))}
function roleMetrics(rows){const cleared=rows.filter(clearedPackage),pending=rows.filter(pendingPackage),value=cleared.reduce((n,p)=>n+packageValue(p),0),outstanding=pending.reduce((n,p)=>n+packageValue(p),0);return {cleared,pending,value,outstanding}}
function departmentOverview(){const all=state.data.packages||[],role=state.role,rows=role==='sales_rep'?myPackages():all,stats=roleMetrics(rows),notices=(state.data.notifications||[]).filter(n=>String(n.status||'').toUpperCase()==='PENDING').length;let cards;if(role==='sales_rep')cards=[metric('My packages',rows.length,'Packages assigned to you','blue'),metric('Cleared value',money(stats.value),'Cleared packages only','green'),metric('Pending client payments',stats.pending.length,'Awaiting payment or release','amber'),metric('My commission',money((state.data.commissions||[]).filter(c=>String(c.employee_id||c.employee_email||'').toLowerCase().includes(String(state.session?.user?.id||'').toLowerCase())).reduce((n,c)=>n+Number(c.amount||c.commission_amount||0),0)),'Live commission records','blue')];else if(role==='logistics_manager')cards=[metric('Warehouse packages',all.length,'Registered packages in the workflow','blue'),metric('Ready to release',stats.cleared.length,'Cleared, collected or released','green'),metric('Pending evidence',notices,'Evidence awaiting a package link','amber'),metric('Pending payment value',money(stats.outstanding),'Registered / pending-release packages','red')];else if(role==='finance_manager')cards=[metric('Company revenue',money(stats.value),'Cleared package value','green'),metric('Receivables',money(stats.outstanding),'Packages still pending payment / release','amber'),metric('Evidence to reconcile',notices,'Payment evidence awaiting link','blue'),metric('Cleared packages',stats.cleared.length,'Revenue recognised packages','green')];else cards=[metric('Sales packages',all.length,'Company package portfolio','blue'),metric('Cleared value',money(stats.value),'Cleared package value','green'),metric('Still unpaid',stats.pending.length,'Pending payment / release','amber'),metric('Sales team',((state.data.employees)||[]).filter(e=>String(e.role||'').toLowerCase().includes('sales')).length,'Registered sales roles','blue')];const intro=role==='finance_manager'?'Finance data is calculated from current package and payment records. Expense, tax and invoice integrations can be connected when their backend tables are available.':role==='sales_rep'?'Follow up your assigned packages and send client reminders from one workspace.':role==='logistics_manager'?'Monitor warehouse flow and safely link payment evidence before release.':'See live commercial performance from the shared package database.';return `<div class="role-banner"><div><span>${esc(roleLabel(role))} workspace</span><h2>${esc(intro)}</h2></div><button class="primary" data-goto="${role==='logistics_manager'||role==='finance_manager'?'payments':role==='sales_rep'?'my_packages':'sales_packages'}">Open work queue →</button></div><section class="metrics">${cards.join('')}</section><section class="grid two"><article class="panel"><div class="panel-head"><div><h2>Package money flow</h2><p>Package values reflect their backend status.</p></div></div><div class="flow"><div><b>${rows.length}</b><span>registered packages</span><i style="width:100%"></i></div><div><b>${stats.pending.length}</b><span>pending payment / release</span><i style="width:${Math.max(8,stats.pending.length/Math.max(1,rows.length)*100)}%"></i></div><div><b>${stats.cleared.length}</b><span>cleared / released</span><i style="width:${Math.max(8,stats.cleared.length/Math.max(1,rows.length)*100)}%"></i></div></div></article><article class="panel"><div class="panel-head"><div><h2>Quick actions</h2><p>Tools available to your department.</p></div></div><div class="quick-grid">${role==='sales_rep'?`<button data-goto="my_packages">View assigned packages</button><button data-goto="reminders">Copy client reminder</button><button data-goto="my_commissions">View commissions</button>`:role==='logistics_manager'?`<button data-goto="warehouse_packages">Review warehouse packages</button><button data-goto="payments">Link payment evidence</button><button data-goto="release_queue">Open release queue</button>`:role==='finance_manager'?`<button data-goto="finance_receivables">Review receivables</button><button data-goto="payments">Reconcile evidence</button><button data-goto="finance_reports">Open reports</button>`:`<button data-goto="sales_packages">Review packages</button><button data-goto="team_performance">View team performance</button><button data-goto="commissions">Review commissions</button>`}</div></article></section><section class="panel"><div class="panel-head"><div><h2>Latest packages</h2><p>Live records from the shared backend.</p></div></div>${packageTable(rows.slice(0,8),'')}</section>`}
function departmentPackages(title,rows,actions=true){return `<section class="role-banner compact"><div><span>${esc(roleLabel(state.role))}</span><h2>${esc(title)}</h2></div><button class="text-btn" data-goto="overview">Back to overview →</button></section>${packageTable(rows,'')}`}
function remindersView(){const rows=myPackages();return `<section class="panel"><div class="panel-head"><div><h2>Client reminders</h2><p>Choose a package then copy its English or Chinese warehouse reminder.</p></div></div>${packageTable(rows,'')}</section>`}
function performanceView(){const rows=state.data.packages||[],staff=(state.data.employees||[]).filter(e=>String(e.role||'').toLowerCase().includes('sales'));return `<section class="panel"><div class="panel-head"><div><h2>Sales team performance</h2><p>Current package flow by registered sales staff.</p></div></div>${staff.length?staff.map(e=>{const name=e.full_name||e.name||e.email;const assigned=rows.filter(p=>String(p.sales_rep||p.assigned_to||p.registered_by||'').toLowerCase().includes(String(name).toLowerCase()));const total=assigned.reduce((n,p)=>n+packageValue(p),0);return `<div class="staff-performance"><div><b>${esc(name)}</b><small>${esc(e.role||'Sales')}</small></div><div><b>${assigned.length}</b><small>packages</small></div><div><b>${money(total)}</b><small>package value</small></div></div>`}).join(''):'<div class="empty">No registered sales staff returned from the backend.</div>'}</section>`}
function releaseQueue(){const rows=(state.data.packages||[]).filter(p=>clearedPackage(p));return departmentPackages('Cleared package release queue',rows)}
function financeModule(title,description,rows,emptyText){return `<section class="role-banner compact"><div><span>FINANCE MANAGER</span><h2>${esc(title)}</h2><p>${esc(description)}</p></div></section>${rows?.length?`<section class="panel">${packageTable(rows,'')}</section>`:`<section class="panel finance-empty"><h2>${esc(title)}</h2><p>${esc(emptyText||'This workspace will become live when the corresponding finance backend table is connected.')}</p><span>Backend setup pending</span></section>`}`}
function financeView(page){const rows=state.data.packages||[],pending=rows.filter(pendingPackage),cleared=rows.filter(clearedPackage);if(page==='finance_receivables')return financeModule('Receivables','Registered packages remain receivable until payment evidence is linked and the package is cleared.',pending,'No outstanding package receivables are currently returned.');if(page==='finance_profitability')return financeModule('Package profitability','Cleared package values are available now; cost, expense and margin fields can be connected with finance backend data.',cleared,'No cleared packages are available for profitability review.');const config={finance_invoices:['Invoices & billing','Create and manage invoice records when the finance invoice backend is available.'],finance_expenses:['Expenses','Expense capture, category approval and monthly reporting are ready for the finance backend connection.'],finance_payables:['Payables','Supplier bills and payment approvals will appear here once supplier and expense tables are connected.'],finance_tax:['KRA & tax','KRA/eTIMS readiness, invoice references and statutory reporting will be connected to the finance integration.'],finance_reports:['Reports','Exportable revenue, receivables, expense and cash-flow reports will be supplied by the finance reporting backend.']}[page]||['Finance workspace',''];return financeModule(config[0],config[1],null)}
function roleContent(){const role=state.role;if(role==='admin'){const views={overview,shipments,payments,staff,commissions,announcements,audit};return (views[state.page]||overview)()}if(state.page==='overview')return departmentOverview();if(role==='sales_rep'){if(state.page==='my_packages')return departmentPackages('My assigned packages',myPackages());if(state.page==='reminders')return remindersView();if(state.page==='my_commissions')return commissions()}if(role==='sales_manager'){if(state.page==='sales_packages')return departmentPackages('Sales packages',state.data.packages||[]);if(state.page==='team_performance')return performanceView();if(state.page==='commissions')return commissions()}if(role==='logistics_manager'){if(state.page==='warehouse_packages')return departmentPackages('Warehouse packages',state.data.packages||[]);if(state.page==='payments')return payments();if(state.page==='release_queue')return releaseQueue()}if(role==='finance_manager'){if(state.page==='payments')return payments();return financeView(state.page)}return departmentOverview()}
function announcements(){return broadcasts()}
function render(){if(!state.session)return renderLogin();$('#app').innerHTML=shell(state.busy?loading():roleContent());bind()}
window.addEventListener('error', event => { app.innerHTML=`<div class="empty">Unable to start DEX Admin Console: ${esc(event.error?.message || event.message)}<br>Please share this message with support.</div>`; });
(async()=>{state.connection={...DEFAULT_CONNECTION,...await window.dexAdmin.getConnection()};state.session=await window.dexAdmin.getSession();if(state.session&&state.connection.url&&state.connection.key){try{await hydrateIdentity();await refreshData()}catch(e){await window.dexAdmin.clearSession();state.session=null;toast(e.message,'error');renderLogin()}}else renderLogin()})();

/* Live Finance Workspace --------------------------------------------------
   Kept at the end of this legacy renderer so these production implementations
   override the earlier compatibility placeholders without changing DEX UI. */
async function financeRequest(path, options={}) { return adminRequest(`/api/public/finance/${path}`, options); }
function financeRows(){return state.data.finance||{invoices:[],expenses:[],closes:[],approvals:[],packages:[],payment_notifications:[],settings:null};}
function amount(value){return Number(value||0)||0}
function financeInvoiceTotal(){return financeRows().invoices.reduce((sum,x)=>sum+amount(x.total),0)}
function financeExpensesTotal(){return financeRows().expenses.filter(x=>['approved','paid'].includes(String(x.status).toLowerCase())).reduce((sum,x)=>sum+amount(x.amount),0)}
async function refreshData(){state.busy=true;render();const get=async p=>{try{return await request(p)}catch(e){console.warn(e);return[]}};const [packages,notifications,commissions,audits,broadcasts,employees,revenue,finance]=await Promise.all([get('rest/v1/cargo_packages?select=*&order=registered_at.desc&limit=500'),get('rest/v1/payment_notifications?select=*&order=uploaded_at.desc&limit=200'),get('rest/v1/commissions?select=*&order=created_at.desc&limit=300'),get('rest/v1/audit_logs?select=*&order=timestamp.desc&limit=150'),get('rest/v1/broadcast_messages?select=*&order=timestamp.desc&limit=50'),adminRequest('/api/public/admin/employees').then(x=>x.employees||[]).catch(()=>get('rest/v1/employees?select=*&order=full_name.asc')),adminRequest('/api/public/revenue-summary').catch(()=>null),(state.role==='finance_manager'||state.role==='admin')?financeRequest('workspace').catch(e=>{console.warn('Finance workspace unavailable',e);return null}):Promise.resolve(null)]);state.data={packages,notifications,commissions,audits,broadcasts,employees,revenue,finance};state.busy=false;render()}
function financeModal(title,inner){const modal=document.createElement('div');modal.style.cssText='position:fixed;inset:0;background:#020a11d9;z-index:80;display:grid;place-items:center;padding:18px;overflow:auto';modal.innerHTML=`<div style="position:relative;width:min(620px,100%);max-height:92vh;overflow:auto;background:#0d1e2b;border:1px solid #34536a;border-radius:16px;padding:28px"><button class="modal-close" style="position:absolute;right:15px;top:10px;border:0;background:transparent;color:#fff;font-size:24px">×</button><p class="eyebrow">DEX LOGISTICS · FINANCE</p><h2>${esc(title)}</h2>${inner}</div>`;document.body.append(modal);modal.querySelector('.modal-close').onclick=()=>modal.remove();return modal}
function packageOptions(selected=''){return (state.data.packages||[]).map(p=>`<option value="${esc(p.id)}" ${String(p.id)===String(selected)?'selected':''}>${esc(p.id)} · ${esc(p.consignee)} · ${money(packageValue(p))}</option>`).join('')}
function newInvoice(){const modal=financeModal('Create package invoice',`<p class="muted">Create a draft invoice from a registered DEX package. It can be approved and submitted to Deitax afterwards.</p><form id="finance-invoice-form"><label>Package<select name="package_id" required><option value="">Choose package…</option>${packageOptions()}</select></label><label>Customer name<input name="customer_name" required placeholder="Client name"></label><label>Customer phone<input name="customer_phone" placeholder="07…"></label><label>Due date<input name="due_date" type="date"></label><label>Payment method<select name="payment_method"><option value="mpesa">M-Pesa</option><option value="bank">Bank transfer</option><option value="cash">Cash</option><option value="other">Other</option></select></label><label>VAT rate (%)<input name="tax_rate" type="number" min="0" step="0.01" value="0"></label><label>Notes<textarea name="notes" placeholder="Optional internal note"></textarea></label><button class="primary wide">Create draft invoice</button></form>`);modal.querySelector('#finance-invoice-form').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target)),pkg=(state.data.packages||[]).find(p=>String(p.id)===String(f.package_id));if(!pkg)return toast('Select a package.','error');const customer=String(f.customer_name||pkg.consignee||'').trim();try{await financeRequest('invoices',{method:'POST',body:JSON.stringify({customer_name:customer,customer_phone:f.customer_phone||pkg.phone||null,due_date:f.due_date||null,payment_method:f.payment_method,tax_rate:Number(f.tax_rate||0),notes:f.notes||null,items:[{description:`DEX cargo package ${pkg.tracking_number||pkg.id}`,quantity:1,unit_price:packageValue(pkg),package_id:pkg.id}]})});modal.remove();toast('Draft invoice created in the shared finance ledger.');await refreshData()}catch(err){toast(`Invoice was not created: ${err.message}`,'error')}}}
function newExpense(){const modal=financeModal('Record expense',`<form id="finance-expense-form"><label>Supplier<input name="supplier_name" required placeholder="Supplier or payee"></label><label>Category<select name="category"><option>Operations</option><option>Transport</option><option>Warehouse</option><option>Utilities</option><option>Payroll</option><option>Marketing</option><option>Professional services</option><option>Other</option></select></label><label>Amount (KES)<input name="amount" type="number" min="0" step="0.01" required></label><label>Expense date<input name="expense_date" type="date" value="${new Date().toISOString().slice(0,10)}"></label><label>Payment method<select name="payment_method"><option value="mpesa">M-Pesa</option><option value="bank">Bank transfer</option><option value="cash">Cash</option><option value="credit">Credit</option></select></label><label>Package (optional)<select name="package_id"><option value="">Not package-specific</option>${packageOptions()}</select></label><label>Receipt URL (optional)<input name="receipt_url" placeholder="https://…"></label><label>Description<textarea name="description" placeholder="What was purchased and why?"></textarea></label><button class="primary wide">Submit expense</button></form>`);modal.querySelector('#finance-expense-form').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));try{await financeRequest('expenses',{method:'POST',body:JSON.stringify({...f,amount:Number(f.amount)})});modal.remove();toast('Expense submitted to the shared finance ledger.');await refreshData()}catch(err){toast(`Expense was not saved: ${err.message}`,'error')}}}
async function financeInvoiceAction(id,action){try{await financeRequest('invoices',{method:'PATCH',body:JSON.stringify({invoice_id:id,action})});toast(`Invoice ${action}d.`);await refreshData()}catch(e){toast(`Invoice action failed: ${e.message}`,'error')}}
async function financeExpenseAction(id,action){try{await financeRequest('expenses',{method:'PATCH',body:JSON.stringify({expense_id:id,action})});toast(`Expense marked ${action}.`);await refreshData()}catch(e){toast(`Expense action failed: ${e.message}`,'error')}}
async function submitEtims(id){try{const result=await financeRequest('submit-etims',{method:'POST',body:JSON.stringify({invoice_id:id})});toast(result.ok?`eTIMS receipt accepted${result.control_code?` · ${result.control_code}`:''}.`:'Invoice submitted to Deitax and is awaiting confirmation.');await refreshData()}catch(e){toast(`eTIMS submission failed: ${e.message}`,'error')}}
function financeInvoiceTable(invoices){return `<div class="table-wrap"><table><thead><tr><th>Invoice</th><th>Client</th><th>Total</th><th>Due</th><th>Status</th><th>eTIMS / action</th></tr></thead><tbody>${invoices.map(x=>{const state=String(x.status||'draft').toLowerCase();const etims=x.etims_control_code||x.etims_invoice_number||x.etims_submission_id;return `<tr><td><b>${esc(x.invoice_number)}</b><br><small>${date(x.created_at)}</small></td><td>${esc(x.customer_name)}<br><small>${esc(x.customer_phone)}</small></td><td>${money(x.total)}</td><td>${x.due_date?esc(x.due_date):'—'}</td><td>${status(state)}</td><td>${etims?`<b>${esc(etims)}</b>`:state==='draft'?`<button class="row-btn" data-finance-invoice="${x.id}" data-finance-action="approve">Approve</button> <button class="row-btn" data-finance-etims="${x.id}">Send eTIMS</button>`:state==='approved'||state==='submitted'?`<button class="row-btn" data-finance-etims="${x.id}">Send / retry eTIMS</button>`:'—'}</td></tr>`}).join('')||'<tr><td colspan="6" class="muted">No invoices have been created yet.</td></tr>'}</tbody></table></div>`}
function financeExpensesTable(expenses){return `<div class="table-wrap"><table><thead><tr><th>Date</th><th>Supplier</th><th>Category</th><th>Amount</th><th>Status</th><th>Action</th></tr></thead><tbody>${expenses.map(x=>{const s=String(x.status||'draft').toLowerCase();return `<tr><td>${esc(x.expense_date)}</td><td><b>${esc(x.supplier_name)}</b><br><small>${esc(x.description)}</small></td><td>${esc(x.category)}</td><td>${money(x.amount)}</td><td>${status(s)}</td><td>${s==='submitted'?`<button class="row-btn" data-finance-expense="${x.id}" data-finance-expense-action="approve">Approve</button>`:s==='approved'?`<button class="row-btn" data-finance-expense="${x.id}" data-finance-expense-action="paid">Mark paid</button>`:'—'}</td></tr>`}).join('')||'<tr><td colspan="6" class="muted">No expenses have been recorded yet.</td></tr>'}</tbody></table></div>`}
function financeView(page){const f=financeRows(),packages=f.packages?.length?f.packages:(state.data.packages||[]),pending=packages.filter(pendingPackage),cleared=packages.filter(clearedPackage),invoices=f.invoices||[],expenses=f.expenses||[];const revenue=cleared.reduce((n,p)=>n+packageValue(p),0),expensesPaid=financeExpensesTotal(),invoiced=financeInvoiceTotal(),etims=f.settings?.etims_status||'not connected';if(!state.data.finance)return `<section class="panel finance-empty"><h2>Finance backend not available</h2><p>The desktop app is ready, but the hosted backend has not yet been deployed with the finance API or the finance SQL migrations have not been applied.</p><span>Run the finance migrations and deploy the latest backend.</span></section>`;if(page==='finance_invoices')return `<section class="role-banner compact"><div><span>LIVE FINANCE LEDGER</span><h2>Invoices & billing</h2><p>Create package invoices, approve them and submit to eTIMS from one queue.</p></div><button class="primary" data-finance-new-invoice>+ New invoice</button></section><section class="metrics">${metric('Invoice value',money(invoiced),'All ledger invoices','blue')}${metric('Outstanding invoices',money(invoices.filter(x=>!['accepted','cancelled','credited'].includes(String(x.status).toLowerCase())).reduce((n,x)=>n+amount(x.total),0)),'Draft, approved or submitted','amber')}${metric('Accepted eTIMS',invoices.filter(x=>String(x.status).toLowerCase()==='accepted').length,'KRA receipt accepted','green')}</section><section class="panel">${financeInvoiceTable(invoices)}</section>`;if(page==='finance_expenses')return `<section class="role-banner compact"><div><span>LIVE FINANCE LEDGER</span><h2>Expenses</h2><p>Capture, approve and mark operating costs paid.</p></div><button class="primary" data-finance-new-expense>+ Record expense</button></section><section class="metrics">${metric('Approved / paid',money(expensesPaid),'Included in profit view','red')}${metric('Awaiting approval',expenses.filter(x=>String(x.status).toLowerCase()==='submitted').length,'Submitted expenses','amber')}${metric('Expense records',expenses.length,'Shared ledger entries','blue')}</section><section class="panel">${financeExpensesTable(expenses)}</section>`;if(page==='finance_receivables')return `<section class="role-banner compact"><div><span>LIVE PACKAGE RECEIVABLES</span><h2>Receivables</h2><p>Packages remain receivable until payment evidence is linked and cleared.</p></div><button class="primary" data-goto="payments">Reconcile evidence →</button></section><section class="metrics">${metric('Outstanding value',money(pending.reduce((n,p)=>n+packageValue(p),0)),'Pending payment / release','amber')}${metric('Outstanding packages',pending.length,'Needs follow-up','red')}${metric('Payment evidence',f.payment_notifications.filter(n=>String(n.status).toUpperCase()!=='LINKED').length,'Awaiting package link','blue')}</section>${packageTable(pending,'Open receivables')}`;if(page==='finance_payables')return `<section class="role-banner compact"><div><span>LIVE PAYABLES</span><h2>Payables</h2><p>Approved supplier expenses waiting for settlement.</p></div><button class="primary" data-finance-new-expense>+ Record payable</button></section><section class="metrics">${metric('Due to suppliers',money(expenses.filter(x=>['submitted','approved'].includes(String(x.status).toLowerCase())).reduce((n,x)=>n+amount(x.amount),0)),'Submitted or approved expenses','amber')}${metric('Paid expenses',money(expenses.filter(x=>String(x.status).toLowerCase()==='paid').reduce((n,x)=>n+amount(x.amount),0)),'Settled costs','green')}</section><section class="panel">${financeExpensesTable(expenses.filter(x=>['submitted','approved','paid'].includes(String(x.status).toLowerCase())))}</section>`;if(page==='finance_profitability')return `<section class="role-banner compact"><div><span>LIVE PROFITABILITY</span><h2>Package profitability</h2><p>Revenue is recognised from cleared package values; approved and paid operating expenses reduce the result.</p></div></section><section class="metrics">${metric('Cleared revenue',money(revenue),'Cleared packages only','green')}${metric('Operating expenses',money(expensesPaid),'Approved / paid ledger costs','red')}${metric('Operating margin',money(revenue-expensesPaid),'Before commissions and tax','blue')}</section>${packageTable(cleared,'Revenue-recognised packages')}`;if(page==='finance_tax')return `<section class="role-banner compact"><div><span>DEITAX · KRA eTIMS</span><h2>KRA & tax</h2><p>Monitor eTIMS readiness and submit approved invoices. Provider credentials stay only on the backend.</p></div></section><section class="metrics">${metric('eTIMS status',String(etims).replaceAll('_',' '),'From finance settings','blue')}${metric('KRA PIN',f.settings?.kra_pin||'Not configured','Legal entity setting','amber')}${metric('Submission queue',invoices.filter(x=>!['accepted','cancelled','credited'].includes(String(x.status).toLowerCase())).length,'Invoice action required','red')}</section><section class="panel"><div class="panel-head"><div><h2>eTIMS submissions</h2><p>Accepted invoices show their returned control code.</p></div></div>${financeInvoiceTable(invoices)}</section>`;if(page==='finance_reports')return `<section class="role-banner compact"><div><span>LIVE REPORTING</span><h2>Finance reports</h2><p>Export current ledger data for daily operations and management review.</p></div><button class="primary" data-finance-export>Export finance CSV</button></section><section class="metrics">${metric('Recognised revenue',money(revenue),'Cleared packages','green')}${metric('Invoiced',money(invoiced),'Finance invoice ledger','blue')}${metric('Expenses',money(expensesPaid),'Approved / paid','red')}${metric('Operating result',money(revenue-expensesPaid),'Before commissions and tax','amber')}</section><section class="panel"><div class="panel-head"><div><h2>Month-end closes</h2><p>Close records are retained in the backend audit trail.</p></div></div><div class="table-wrap"><table><thead><tr><th>Period</th><th>Revenue</th><th>Expenses</th><th>Commissions</th><th>Net profit</th><th>Status</th></tr></thead><tbody>${(f.closes||[]).map(x=>`<tr><td>${esc(x.period)}</td><td>${money(x.revenue)}</td><td>${money(x.expenses)}</td><td>${money(x.commissions)}</td><td>${money(x.net_profit)}</td><td>${status(x.status)}</td></tr>`).join('')||'<tr><td colspan="6" class="muted">No closed accounting periods yet.</td></tr>'}</tbody></table></div></section>`;return departmentOverview()}
function exportFinance(){const f=financeRows(),lines=['Type,Reference,Date,Counterparty,Amount,Status',...(f.invoices||[]).map(x=>['Invoice',x.invoice_number,x.issue_date,x.customer_name,x.total,x.status]),...(f.expenses||[]).map(x=>['Expense',x.id,x.expense_date,x.supplier_name,-amount(x.amount),x.status])].map(row=>row.map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([lines],{type:'text/csv'}));a.download=`dex-finance-${new Date().toISOString().slice(0,10)}.csv`;a.click();URL.revokeObjectURL(a.href)}
function bind(){document.querySelectorAll('[data-page],[data-goto]').forEach(b=>b.addEventListener('click',()=>{state.page=b.dataset.page||b.dataset.goto;render()}));$('#refresh')?.addEventListener('click',refreshData);$('#signout')?.addEventListener('click',async()=>{await window.dexAdmin.clearSession();state.session=null;state.data={};renderLogin()});$('#add-staff')?.addEventListener('click',createEmployee);$('#payment-upload')?.addEventListener('submit',e=>{e.preventDefault();uploadPayment(e.target)});$('#evidence-type')?.addEventListener('change',e=>{const image=e.target.value==='IMAGE';$('#image-field').style.display=image?'':'none';$('#note-field').style.display=image?'':'none';$('#text-field').style.display=image?'none':''});document.querySelectorAll('[data-evidence-image]').forEach(b=>b.addEventListener('click',()=>viewEvidenceImage(b.dataset.evidenceImage)));document.querySelectorAll('[data-evidence-thumb]').forEach(loadEvidenceThumbnail);document.querySelectorAll('[data-evidence-text]').forEach(b=>b.addEventListener('click',()=>viewEvidenceText(b.dataset.evidenceText)));document.querySelectorAll('[data-delete-employee]').forEach(b=>b.addEventListener('click',()=>deleteEmployee(b.dataset.deleteEmployee)));document.querySelectorAll('[data-link-payment]').forEach(b=>b.addEventListener('click',()=>linkPayment(b.dataset.linkPayment)));document.querySelectorAll('[data-employee]').forEach(b=>b.addEventListener('click',()=>setEmployee(b.dataset.employee,b.dataset.active!=='true')));document.querySelectorAll('[data-commission]').forEach(b=>b.addEventListener('click',()=>commission(b.dataset.commission,'approve_commission')));document.querySelectorAll('[data-paid]').forEach(b=>b.addEventListener('click',()=>commission(b.dataset.paid,'mark_commission_paid')));document.querySelectorAll('[data-track]').forEach(b=>b.addEventListener('click',()=>openShipment(b.dataset.track)));document.querySelectorAll('[data-reminder]').forEach(b=>b.addEventListener('click',()=>copyReminder(b.dataset.reminder)));document.querySelectorAll('[data-photo]').forEach(b=>{loadPackagePhoto(b);b.addEventListener('click',()=>viewPhoto(b.dataset.photo))});$('#broadcast-form')?.addEventListener('submit',sendBroadcast);$('#export-audit')?.addEventListener('click',exportAudit);document.querySelector('[data-finance-new-invoice]')?.addEventListener('click',newInvoice);document.querySelector('[data-finance-new-expense]')?.addEventListener('click',newExpense);document.querySelector('[data-finance-export]')?.addEventListener('click',exportFinance);document.querySelectorAll('[data-finance-invoice]').forEach(b=>b.addEventListener('click',()=>financeInvoiceAction(b.dataset.financeInvoice,b.dataset.financeAction)));document.querySelectorAll('[data-finance-expense]').forEach(b=>b.addEventListener('click',()=>financeExpenseAction(b.dataset.financeExpense,b.dataset.financeExpenseAction)));document.querySelectorAll('[data-finance-etims]').forEach(b=>b.addEventListener('click',()=>submitEtims(b.dataset.financeEtims)))}

/* Manifest import is available to both company administrators and Sales
   Managers. The server previews the spreadsheet before it registers packages. */
function navItems(role){const admin=[['overview','Overview','◫'],['shipments','Packages','▣'],['manifests','Import manifest','⇧'],['payments','Payments','◉'],['staff','Staff','♙'],['commissions','Commissions','◈'],['announcements','Announcements','◌'],['audit','Audit log','◷']];const salesRep=[['overview','My overview','◫'],['my_packages','My packages','▣'],['reminders','Client reminders','◌'],['my_commissions','My commissions','◈'],['announcements','Announcements','◌']];const salesManager=[['overview','Sales overview','◫'],['sales_packages','Sales packages','▣'],['manifests','Import manifest','⇧'],['team_performance','Team performance','◈'],['commissions','Team commissions','◈'],['announcements','Announcements','◌']];const logistics=[['overview','Warehouse overview','◫'],['warehouse_packages','Warehouse packages','▣'],['payments','Payment evidence','◉'],['release_queue','Release queue','✓'],['announcements','Announcements','◌']];const finance=[['overview','Finance overview','◫'],['finance_invoices','Invoices & billing','▣'],['payments','Payment evidence','◉'],['finance_receivables','Receivables','◈'],['finance_expenses','Expenses','◌'],['finance_payables','Payables','◌'],['finance_profitability','Package profitability','◫'],['finance_tax','KRA & tax','✓'],['finance_reports','Reports','◷']];return role==='admin'?admin:role==='sales_rep'?salesRep:role==='sales_manager'?salesManager:role==='logistics_manager'?logistics:finance}
function pageTitle(){const labels={overview:'Overview',manifests:'Manifest import',my_packages:'My packages',reminders:'Client reminders',my_commissions:'My commissions',sales_packages:'Sales packages',team_performance:'Team performance',warehouse_packages:'Warehouse packages',release_queue:'Release queue',finance_invoices:'Invoices & billing',finance_receivables:'Receivables',finance_expenses:'Expenses',finance_payables:'Payables',finance_profitability:'Package profitability',finance_tax:'KRA & tax',finance_reports:'Reports',shipments:'Packages',payments:'Payments',staff:'Staff',commissions:'Commissions',announcements:'Announcements',audit:'Audit log'};return labels[state.page]||'DEX Admin'}
function manifestView(){const rows=state.data.packages||[],groups=[['general','General cargo · air'],['special','Special cargo · air'],['sea','Sea cargo']];return `<section class="role-banner compact"><div><span>EXCEL BULK REGISTRATION</span><h2>Import cargo manifest</h2><p>Upload General Cargo, Special Cargo, or Sea Cargo Excel files. Review extracted rows before they become shared package records.</p></div></section><section class="grid two"><article class="panel compose"><div class="panel-head"><div><h2>1. Preview Excel manifest</h2><p>Only .xlsx files. Nothing is saved until confirmation.</p></div></div><form id="manifest-form"><label>Cargo category<select name="category"><option value="general">General cargo · Air</option><option value="special">Special cargo · Air</option><option value="sea">Sea cargo</option></select></label><label>Manifest Excel file<input name="file" type="file" accept=".xlsx,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" required></label><button class="primary wide">Read and preview manifest</button></form></article><article class="panel"><div class="panel-head"><div><h2>Current package categories</h2><p>Imported records appear immediately across dashboard package views.</p></div></div><div class="flow">${groups.map(([key,label])=>{const r=rows.filter(p=>String(p.cargo_category||'general').toLowerCase()===key);return `<div><b>${r.length}</b><span>${esc(label)}</span><i style="width:${Math.max(8,r.length/Math.max(1,rows.length)*100)}%"></i></div>`}).join('')}</div><p class="muted" style="margin-top:18px">The importer extracts tracking number, client, pieces, weight, CBM where present, package charge and item description, then saves each valid row as a package.</p></article></section><div id="manifest-preview"></div>`}
async function previewManifest(form,commit=false){const data=new FormData(form);data.set('commit',String(commit));const response=await fetch(`${ADMIN_BACKEND}/api/public/import-manifest`,{method:'POST',headers:{Authorization:`Bearer ${state.session.access_token}`},body:data});const json=await response.json().catch(()=>({error:'The manifest service returned an unreadable response.'}));if(!response.ok)throw new Error(json.error||'Manifest import failed.');return json}
function renderManifestPreview(preview,form){const target=$('#manifest-preview');if(!target)return;const rows=preview.ready||[];target.innerHTML=`<section class="metrics" style="margin-top:18px">${metric('Rows found',preview.total_rows,'Excel rows read','blue')}${metric('Ready to register',preview.ready_rows,'Valid new packages','green')}${metric('Already registered',preview.duplicate_rows,'Skipped duplicates','amber')}${metric('Needs attention',preview.invalid_rows,'Not imported','red')}</section><section class="grid two"><article class="panel"><div class="panel-head"><div><h2>2. Review extracted packages</h2><p>Only valid, non-duplicate package rows are registered.</p></div></div><div class="table-wrap"><table><thead><tr><th>Tracking</th><th>Client</th><th>Pieces</th><th>Weight</th><th>CBM</th><th>Charge</th></tr></thead><tbody>${rows.map(r=>`<tr><td><b>${esc(r.tracking_number)}</b></td><td>${esc(r.consignee)}</td><td>${esc(r.pcs)}</td><td>${esc(r.weight)}</td><td>${esc(r.volume_cbm)}</td><td>${r.cost==null?'—':money(r.cost)}</td></tr>`).join('')||'<tr><td colspan="6" class="muted">No new valid package rows to register.</td></tr>'}</tbody></table></div></article><article class="panel attention"><div class="panel-head"><div><h2>3. Confirm bulk registration</h2><p>Packages are saved into the shared cargo_packages backend table and shown on all dashboards.</p></div></div><button class="primary wide" id="manifest-commit" ${preview.ready_rows?'':'disabled'}>Register ${preview.ready_rows||0} package(s)</button><p class="muted" style="margin-top:14px">Existing tracking IDs are safely skipped. The selected cargo category is stored with every imported package.</p></article></section>`;$('#manifest-commit')?.addEventListener('click',async()=>{try{const result=await previewManifest(form,true);toast(`${result.imported_rows||0} packages were registered and are now available on dashboards.`);await refreshData()}catch(e){toast(`Manifest was not registered: ${e.message}`,'error')}})}
function shipments(){const rows=state.data.packages||[],groups=[['general','General cargo · Air'],['special','Special cargo · Air'],['sea','Sea cargo']];return `<section class="toolbar"><div class="search"><span>⌕</span><input id="shipment-search" placeholder="Search package, client or phone"></div><button class="primary" data-goto="manifests">⇧ Import manifest</button></section>${groups.map(([key,title])=>packageTable(rows.filter(p=>String(p.cargo_category||'general').toLowerCase()===key),title)).join('')}`}
function roleContent(){const role=state.role;if(role==='admin'){const views={overview,shipments,manifests:manifestView,payments,staff,commissions,announcements,audit};return (views[state.page]||overview)()}if(state.page==='overview')return departmentOverview();if(role==='sales_rep'){if(state.page==='my_packages')return departmentPackages('My assigned packages',myPackages());if(state.page==='reminders')return remindersView();if(state.page==='my_commissions')return commissions()}if(role==='sales_manager'){if(state.page==='manifests')return manifestView();if(state.page==='sales_packages')return departmentPackages('Sales packages',state.data.packages||[]);if(state.page==='team_performance')return performanceView();if(state.page==='commissions')return commissions()}if(role==='logistics_manager'){if(state.page==='warehouse_packages')return departmentPackages('Warehouse packages',state.data.packages||[]);if(state.page==='payments')return payments();if(state.page==='release_queue')return releaseQueue()}if(role==='finance_manager'){if(state.page==='payments')return payments();return financeView(state.page)}return departmentOverview()}
