// External public tracking is a sales follow-up tool. Administrators and the
// warehouse/finance teams keep their operational package view uncluttered.
function packageTable(rows,title='Packages'){const canTrack=['sales_rep','sales_manager'].includes(state.role);return `<section class="panel"><div class="panel-head"><div><h2>${esc(title)}</h2><p>${rows.length} package${rows.length===1?'':'s'}</p></div></div><div class="table-wrap"><table><thead><tr><th>Package image</th><th>Tracking</th><th>Client</th><th>Route / freight</th><th>Amount</th><th>Status</th><th>Actions</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${x.package_photo_url?`<button class="package-thumb" data-photo="${esc(x.package_photo_url)}"><img alt="Package image"><span>View</span></button>`:'<div class="package-thumb empty-thumb">No image</div>'}</td><td><b>${esc(x.tracking_number||x.id)}</b></td><td>${esc(x.consignee)}<br><small>${esc(x.phone)}</small></td><td>${esc(x.origin)} → ${esc(x.dest)}<br><small>${esc(x.mode||x.cargo_category||'Freight mode not set')}</small></td><td>${money(packageValue(x))}</td><td>${status(x.status)}</td><td>${canTrack?`<button class="row-btn" data-external-track="${esc(x.id||x.tracking_number)}">Track</button> `:''}<button class="row-btn" data-reminder="${esc(x.id)}">Copy reminder</button> <button class="row-btn" data-track="${esc(x.id)}">Update</button></td></tr>`).join('')||'<tr><td colspan="7" class="muted">No packages in this group.</td></tr>'}</tbody></table></div></section>`}
// DEX current operational overrides.
function reminderMessage(pkg,language){const name=pkg.consignee||'Customer',tracking=pkg.tracking_number||pkg.id;return language==='zh'?`${tracking} ${name}\n您好，以上空运货物已完成清关，今天可以提货。\n提货地址：Kivi Milimani Hotel & apartment。\nMilimani Road, Nairobi, Kenya\n联系人 1：Thomas 0790821517（中文）\n联系人 2：John 0720329499（本地）`:`${tracking} ${name}\nHello, the above air freight has cleared customs and can be picked up today.\nPickup address: Kivi Milimani Hotel & apartment.\nMilimani Road, Nairobi, Kenya\nContact person 1: Thomas 0790821517 (Chinese)\nContact person 2: John 0720329499 (Local)`}
function copyReminder(id){const pkg=(state.data.packages||[]).find(x=>String(x.id)===String(id));if(!pkg)return toast('Package was not found. Refresh and try again.','error');const modal=packageDialog(`<p class="eyebrow">DEX LOGISTICS · CLIENT REMINDER</p><h2>Copy package reminder</h2><p>Choose the message language for ${esc(pkg.consignee||'Customer')}.</p><div class="dialog-actions"><button class="primary" data-copy-language="en">Copy English</button><button class="secondary" data-copy-language="zh">复制中文</button></div>`);modal.querySelectorAll('[data-copy-language]').forEach(button=>button.onclick=async()=>{const ok=await copyText(reminderMessage(pkg,button.dataset.copyLanguage));toast(ok?'Customer reminder copied to clipboard.':'Could not copy automatically; please try again.','error');if(ok)modal.remove()})}
function commissionEligibleEmployees(){return (state.data.employees||[]).filter(e=>!['admin','finance_manager'].includes(String(e.role||'').toLowerCase()))}
function commissions(){const staff=commissionEligibleEmployees(),allowed=new Set(staff.flatMap(e=>[e.id,e.employee_code]).filter(Boolean)),rows=(state.data.commissions||[]).filter(x=>!allowed.size||allowed.has(x.employee_id)),sum=a=>a.reduce((s,x)=>s+Number(x.amount||x.commission_amount||0),0),byEmployee=staff.map(e=>{const own=rows.filter(x=>x.employee_id===e.id||x.employee_id===e.employee_code);return {...e,total:sum(own),outstanding:sum(own.filter(x=>!['paid','settled'].includes(String(x.status||'').toLowerCase())))}});return `<section class="panel"><div class="panel-head"><div><h2>Employee commissions</h2><p>Finance Managers and Administrators do not receive commission.</p></div><span class="count">${money(sum(rows.filter(x=>!['paid','settled'].includes(String(x.status||'').toLowerCase()))))} outstanding</span></div><div class="table-wrap"><table><thead><tr><th>Employee</th><th>Role</th><th>Commission earned</th><th>Outstanding</th></tr></thead><tbody>${byEmployee.map(e=>`<tr><td><b>${esc(e.full_name||e.email)}</b><br><small>${esc(e.employee_code||'—')}</small></td><td>${esc(e.role)}</td><td>${money(e.total)}</td><td>${money(e.outstanding)}</td></tr>`).join('')||'<tr><td colspan="4" class="muted">No commission yet</td></tr>'}</tbody></table></div></section><section class="panel"><div class="panel-head"><div><h2>Commission ledger</h2><p>Package-payment commissions from the backend.</p></div></div>${rows.length?`<div class="table-wrap"><table><thead><tr><th>Package / reference</th><th>Employee</th><th>Amount</th><th>Status</th><th>Action</th></tr></thead><tbody>${rows.map(c=>{const s=String(c.status||'').toLowerCase();return `<tr><td>${esc(c.reference||c.order_id||c.package_id||'—')}</td><td>${esc(c.employee_id)}</td><td>${money(c.amount||c.commission_amount)}</td><td>${status(c.status)}</td><td>${s==='pending'?`<button class="row-btn approve" data-commission="${c.id}">Approve</button>`:s==='approved'?`<button class="row-btn paid" data-paid="${c.id}">Mark paid</button>`:'—'}</td></tr>`}).join('')}</tbody></table></div>`:'<div class="empty">No commission yet</div>'}</section>`}
function staff(){const rows=state.data.employees||[],eligible=commissionEligibleEmployees(),commissions=state.data.commissions||[],totals=eligible.map(e=>({...e,earned:commissions.filter(c=>c.employee_id===e.id||c.employee_id===e.employee_code).reduce((s,c)=>s+Number(c.amount||c.commission_amount||0),0)})),max=Math.max(1,...totals.map(x=>x.earned));return `<section class="panel"><div class="panel-head"><div><h2>Employee commissions</h2><p>Live commission totals. Administrators and Finance Managers are excluded.</p></div></div>${totals.map(e=>`<div style="display:grid;grid-template-columns:170px 1fr 100px;gap:12px;align-items:center;margin:13px 0"><b>${esc(e.full_name)}</b><div style="height:11px;background:#173044;border-radius:20px;overflow:hidden"><i style="display:block;height:100%;width:${e.earned/max*100}%;background:linear-gradient(90deg,#3ea8fa,#49d4a5)"></i></div><span>${money(e.earned)}</span></div>`).join('')||'<div class="empty">No commission yet</div>'}</section><section class="toolbar"><p class="muted">Manage staff through the secured DEX administrator backend.</p><button class="primary" id="add-staff">+ Add team member</button></section><section class="panel"><div class="table-wrap"><table><thead><tr><th>Employee</th><th>Code</th><th>Role</th><th>Access</th><th></th></tr></thead><tbody>${rows.map(x=>`<tr><td><b>${esc(x.full_name)}</b><br><small>${esc(x.email)}</small></td><td>${esc(x.employee_code)}</td><td>${status(x.role)}</td><td><button class="toggle ${x.is_active?'on':''}" data-employee="${x.id}" data-active="${x.is_active}"><i></i>${x.is_active?'Active':'Inactive'}</button></td><td>${x.role==='admin'?'—':`<button class="row-btn" data-delete-employee="${x.id}">Delete</button>`}</td></tr>`).join('')}</tbody></table></div></section>`}
function overview(){const p=state.data.packages||[],summary=state.data.revenue||{},now=new Date(),inMonth=x=>{const d=new Date(x.cleared_at||x.paid_at||x.registered_at||x.imported_at||x.created_at||0);return d.getFullYear()===now.getFullYear()&&d.getMonth()===now.getMonth()},cleared=p.filter(x=>['cleared','collected','released'].includes(String(x.status||'').toLowerCase())),unpaid=p.filter(x=>['registered','awaiting_payment','received'].includes(String(x.status||'').toLowerCase())),monthly=p.filter(inMonth),monthCleared=monthly.filter(x=>['cleared','collected','released'].includes(String(x.status||'').toLowerCase())),value=xs=>xs.reduce((s,x)=>s+packageValue(x),0),totalRevenue=Number(summary.revenue?.total??summary.gross_income??value(cleared)),pendingValue=Number(summary.pending_release?.value??summary.packages?.pending_release_value??value(unpaid)),monthRevenue=value(monthCleared),max=Math.max(1,monthly.length,unpaid.length,cleared.length);return `<section class="role-banner compact"><div><span>DEX ADMIN · ${esc(now.toLocaleString('en-KE',{month:'long',year:'numeric'}).toUpperCase())}</span><h2>Monthly operations snapshot</h2><p>Live package, payment and revenue figures from the shared backend.</p></div></section><section class="metrics">${metric('This month: packages',monthly.length,'Registered this calendar month','blue')}${metric('This month: cleared',monthCleared.length,money(monthRevenue)+' recognised revenue','green')}${metric('Pending payments',unpaid.length,money(pendingValue)+' pending release','red')}${metric('Total company revenue',money(totalRevenue),'Cleared package value','amber')}</section><section class="grid two"><article class="panel"><div class="panel-head"><div><h2>Monthly package flow</h2><p>Current package status from the backend.</p></div></div><div class="flow">${[['this month registered',monthly.length],['still unpaid',unpaid.length],['cleared / released',cleared.length]].map(([n,c])=>`<div><b>${c}</b><span>${n}</span><i style="width:${Math.max(8,c/max*100)}%"></i></div>`).join('')}</div></article><article class="panel treasury"><div class="panel-head"><div><h2>Monthly money flow</h2><p>Only cleared or released packages are revenue.</p></div></div><div class="treasury-grid"><div><small>This-month revenue</small><b>${money(monthRevenue)}</b></div><div><small>Total revenue</small><b>${money(totalRevenue)}</b></div><div><small>Pending value</small><b>${money(pendingValue)}</b></div><div><small>Cleared packages</small><b>${cleared.length}</b></div></div></article></section><section class="panel"><div class="panel-head"><div><h2>Latest packages</h2><p>Live package records, including imported manifests.</p></div><button class="text-btn" data-goto="shipments">View all →</button></div>${packageTable(p.slice(0,10),'')}</section>`}
// Packages are always a live operational list. Monthly grouping is used only
// for overview metrics; never filter package records by month.
function livePackageRows(){return state.data.packages||[]}
function packageTable(rows,title='Packages'){const canTrack=String(state.role||'').toLowerCase()!=='finance_manager';return `<section class="panel"><div class="panel-head"><div><h2>${esc(title)}</h2><p>${rows.length} live package${rows.length===1?'':'s'}</p></div></div><div class="table-wrap"><table><thead><tr><th>Tracking</th><th>Client</th><th>Category</th><th>Route / freight</th><th>Pieces</th><th>Weight</th><th>Price</th><th>Status</th><th>Actions</th></tr></thead><tbody>${rows.map(x=>`<tr><td><b>${esc(x.tracking_number||x.id)}</b></td><td>${esc(x.consignee)}${x.phone?`<br><small>${esc(x.phone)}</small>`:''}</td><td>${status(x.cargo_category||'general')}</td><td>${esc(x.origin||'—')} → ${esc(x.dest||'—')}<br><small>${esc(x.mode||'—')}</small></td><td>${esc(x.pcs??'—')}</td><td>${esc(x.weight??'—')}</td><td>${money(packageValue(x))}</td><td>${status(x.status)}</td><td>${canTrack?`<button class="row-btn" data-external-track="${esc(x.id||x.tracking_number)}">Track</button> `:''}<button class="row-btn" data-reminder="${esc(x.id)}">Copy reminder</button> <button class="row-btn" data-track="${esc(x.id)}">Update</button></td></tr>`).join('')||'<tr><td colspan="9" class="muted">No packages in this category.</td></tr>'}</tbody></table></div></section>`}
function shipments(){const all=livePackageRows(),selected=state.packageCategory||'all',rows=selected==='cleared'?all.filter(x=>['cleared','collected','released'].includes(String(x.status||'').toLowerCase())):selected==='all'?all:all.filter(x=>String(x.cargo_category||'general').toLowerCase()===selected),tabs=[['all','All packages'],['general','General'],['special','Special'],['sea','Sea'],['cleared','Cleared packages']];return `<section class="toolbar"><div class="search"><span>⌕</span><input id="shipment-search" placeholder="Search all packages, clients or tracking numbers" oninput="const q=this.value.toLowerCase().trim();document.querySelectorAll('.table-wrap tbody tr').forEach(row=>row.hidden=!!q&&!row.textContent.toLowerCase().includes(q))"></div><div class="category-tabs">${tabs.map(([key,label])=>`<button class="${selected===key?'active':''}" onclick="state.packageCategory='${key}';render()">${label}</button>`).join('')}</div>${state.role==='admin'?'<button class="primary" data-goto="manifests">⇧ Import manifest</button>':''}</section>${packageTable(rows,'Live packages')}`}

// Use the backend tracking agent first; retain provider links when an optional
// carrier API is unavailable or the endpoint has not yet been deployed.
async function trackPackage(id){const pkg=(state.data.packages||[]).find(p=>String(p.id)===String(id)||String(p.tracking_number)===String(id));const number=trackingNumber(pkg)||String(id||'').trim();if(!number)return toast('This package has no tracking number.','error');try{const result=await adminRequest(`/api/public/track?number=${encodeURIComponent(number)}`);const events=(result.events||[]).slice(0,8).map(e=>`<div class="action"><span>◉</span><div><b>${esc(e.status||'Update')}</b><small>${esc(e.location||'')} · ${esc(e.time?date(e.time):'')}</small></div></div>`).join('')||'<p class="muted">No carrier checkpoints yet.</p>';const links=result.manual_lookup||{};const modal=packageDialog(`<p class="eyebrow">DEX LOGISTICS · LIVE TRACKING</p><h2>${esc(number)}</h2><p><b>${esc(result.latest_status||'No external update')}</b> · ${result.found_in_system?'DEX package found':'Not in DEX packages'}</p>${events}<div class="status-actions"><button class="row-btn" data-open-tracker="17track">Open 17TRACK</button><button class="row-btn" data-open-tracker="parcels">Open ParcelsApp</button></div>`);modal.querySelectorAll('[data-open-tracker]').forEach(b=>b.onclick=()=>{openTrackingProvider(b.dataset.openTracker,number);modal.remove()})}catch(e){toast(`Tracking service unavailable: ${e.message}`,'error');openTrackingProvider('17track',number)}}
async function saveEtimsSettings(form){const values=Object.fromEntries(new FormData(form));try{const result=await financeRequest('etims-settings',{method:'PUT',body:JSON.stringify({...values,vat_registered:values.vat_registered==='on'})});if(state.data.finance)state.data.finance.settings=result.settings;toast(`eTIMS profile saved · status: ${String(result.settings?.etims_status||'not_connected').replaceAll('_',' ')}`);render()}catch(e){toast(`eTIMS profile could not be saved: ${e.message}`,'error')}}
function etimsFinanceView(){const f=financeRows(),s=f.settings||{};return `<section class="role-banner compact"><div><span>DEITAX · KRA eTIMS</span><h2>KRA & tax profile</h2><p>Maintain the legal entity profile used for compliant invoices. Connection status is calculated by the backend from profile completeness and configured Deitax secrets.</p></div></section><section class="grid two"><article class="panel compose"><div class="panel-head"><div><h2>eTIMS business profile</h2><p>Finance Managers and Administrators can update these settings.</p></div></div><form id="etims-settings-form"><label>Legal business name<input name="legal_name" value="${esc(s.legal_name||'')}" required></label><label>KRA PIN<input name="kra_pin" value="${esc(s.kra_pin||'')}" placeholder="P051234567X" pattern="P[0-9]{9}[A-Za-z]" required></label><label>Branch name<input name="branch_name" value="${esc(s.branch_name||'')}" required></label><label>Invoice prefix<input name="invoice_prefix" value="${esc(s.invoice_prefix||'DEX')}" maxlength="12" required></label><label>eTIMS provider<select name="etims_provider"><option value="deitax" ${s.etims_provider!=='none'?'selected':''}>Deitax</option><option value="none" ${s.etims_provider==='none'?'selected':''}>Not configured</option></select></label><label>Operating mode<select name="etims_mode"><option value="not_configured" ${s.etims_mode==='not_configured'?'selected':''}>Not configured</option><option value="sandbox" ${s.etims_mode==='sandbox'?'selected':''}>Sandbox</option><option value="production" ${s.etims_mode==='production'?'selected':''}>Production</option></select></label><label>eTIMS business ID<input name="etims_business_id" value="${esc(s.etims_business_id||'')}" placeholder="Optional provider business ID"></label><label class="check-row"><input type="checkbox" name="vat_registered" ${s.vat_registered?'checked':''}> VAT registered</label><button class="primary wide">Save eTIMS profile</button></form></article><article class="panel"><div class="panel-head"><div><h2>Connection readiness</h2><p>The server never trusts a manually entered “connected” status.</p></div></div><div class="treasury-grid"><div><small>Derived status</small><b>${esc(String(s.etims_status||'not_connected').replaceAll('_',' '))}</b></div><div><small>Provider credentials</small><b>${f.provider_credentials_configured?'Configured':'Not configured'}</b></div><div><small>Last checked</small><b>${date(s.etims_last_checked_at)}</b></div><div><small>KRA PIN</small><b>${esc(s.kra_pin||'Not configured')}</b></div></div><p class="muted" style="margin-top:18px">Add <code>DEITAX_API_URL</code> and <code>DEITAX_API_KEY</code> as backend secrets before production submissions can be accepted.</p></article></section><section class="panel"><div class="panel-head"><div><h2>Invoice submission queue</h2><p>Approved invoices can be submitted after the profile is ready.</p></div></div>${financeInvoiceTable(f.invoices||[])}</section>`}

// Manifest intake: every active DEX employee can preview and register a workbook.
// The UI displays each normalized financial field while preserving every raw
// workbook column in manifest_data for the details dialog.
function navItems(role){const manifest=['manifests','Import manifest','⇧'];const admin=[['overview','Overview','◫'],['shipments','Packages','▣'],manifest,['payments','Payments','◉'],['staff','Staff','♙'],['commissions','Commissions','◈'],['announcements','Announcements','◌'],['audit','Audit log','◷']];const salesRep=[['overview','My overview','◫'],['my_packages','My packages','▣'],manifest,['reminders','Client reminders','◌'],['my_commissions','My commissions','◈'],['announcements','Announcements','◌']];const salesManager=[['overview','Sales overview','◫'],['sales_packages','Sales packages','▣'],manifest,['team_performance','Team performance','◈'],['commissions','Team commissions','◈'],['announcements','Announcements','◌']];const logistics=[['overview','Warehouse overview','◫'],['warehouse_packages','Warehouse packages','▣'],manifest,['payments','Payment evidence','◉'],['release_queue','Release queue','✓'],['announcements','Announcements','◌']];const finance=[['overview','Finance overview','◫'],['finance_invoices','Invoices & billing','▣'],['payments','Payment evidence','◉'],['finance_receivables','Receivables','◈'],['finance_expenses','Expenses','◌'],['finance_payables','Payables','◌'],['finance_profitability','Package profitability','◫'],['finance_tax','KRA & tax','✓'],['finance_reports','Reports','◷'],manifest];return role==='admin'?admin:role==='sales_rep'?salesRep:role==='sales_manager'?salesManager:role==='logistics_manager'?logistics:finance}
function roleContent(){const role=state.role;if(state.page==='manifests')return manifestView();if(role==='admin'){const views={overview,shipments,payments,staff,commissions,announcements,audit};return (views[state.page]||overview)()}if(state.page==='overview')return departmentOverview();if(role==='sales_rep'){if(state.page==='my_packages')return departmentPackages('My assigned packages',myPackages());if(state.page==='reminders')return remindersView();if(state.page==='my_commissions')return commissions()}if(role==='sales_manager'){if(state.page==='sales_packages')return departmentPackages('Sales packages',state.data.packages||[]);if(state.page==='team_performance')return performanceView();if(state.page==='commissions')return commissions()}if(role==='logistics_manager'){if(state.page==='warehouse_packages')return departmentPackages('Warehouse packages',state.data.packages||[]);if(state.page==='payments')return payments();if(state.page==='release_queue')return releaseQueue()}if(role==='finance_manager'){if(state.page==='payments')return payments();return financeView(state.page)}return departmentOverview()}
function manifestView(){const rows=livePackageRows(),groups=[['general','General cargo · air'],['special','Special cargo · air'],['sea','Sea cargo']];return `<section class="role-banner compact"><div><span>EXCEL BULK REGISTRATION</span><h2>Import cargo manifest</h2><p>Any active DEX employee can upload General, Special, or Sea Cargo Excel files. Every source column is retained with the package.</p></div></section><section class="grid two"><article class="panel compose"><div class="panel-head"><div><h2>1. Preview Excel manifest</h2><p>Only .xlsx files. Nothing is saved until confirmation.</p></div></div><form id="manifest-form"><label>Cargo category<select name="category"><option value="general">General cargo · Air</option><option value="special">Special cargo · Air</option><option value="sea">Sea cargo</option></select></label><label>Manifest Excel file<input name="file" type="file" accept=".xlsx,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" required></label><button class="primary wide">Read and preview manifest</button></form></article><article class="panel"><div class="panel-head"><div><h2>Shared package categories</h2><p>Imported records appear across every dashboard immediately.</p></div></div><div class="flow">${groups.map(([key,label])=>{const r=rows.filter(p=>String(p.cargo_category||'general').toLowerCase()===key);return `<div><b>${r.length}</b><span>${esc(label)}</span><i style="width:${Math.max(8,r.length/Math.max(1,rows.length)*100)}%"></i></div>`}).join('')}</div><p class="muted" style="margin-top:18px">Air cargo: tracking, contact, pieces, chargeable weight, unit price, totals in RMB/USD/KES, payment mode, date and signature. Sea cargo: receipt date/number, pieces, weight, CBM, item, client, container position and billing formula.</p></article></section><div id="manifest-preview"></div>`}
function manifestMoney(value,currency){const n=Number(value);return Number.isFinite(n)?`${currency} ${n.toLocaleString('en-KE',{maximumFractionDigits:2})}`:'—'}
function parseManifestData(x){try{return typeof x?.manifest_data==='string'?JSON.parse(x.manifest_data):x?.manifest_data||{}}catch{return {}}}
// Supports both the new normalized backend columns and packages imported by
// earlier releases, where the Chinese 账单 value was retained only as JSON.
function seaBilling(x){const data=parseManifestData(x),billing=data.billing||{},raw=String(x.billing_formula??billing.raw??'').trim(),match=raw.match(/=\s*([\d,.]+)\s*(KES|RMB|USD|CNY|元|人民币)?/i)||raw.match(/([\d,.]+)\s*(KES|RMB|USD|CNY|元|人民币)/i),amount=x.billing_amount??billing.amount??(match?Number(String(match[1]).replace(/,/g,'')):null),rawCurrency=x.billing_currency??billing.currency??match?.[2]??'',currency=String(rawCurrency).toUpperCase().replace('CNY','RMB').replace('人民币','RMB').replace('元','RMB');return {raw,amount:Number.isFinite(Number(amount))?Number(amount):null,currency:currency||'Calculated charge'}}
function packagePrice(x){const lines=[];if(x.total_price_kes!=null)lines.push(manifestMoney(x.total_price_kes,'KES'));if(x.total_price_usd!=null)lines.push(manifestMoney(x.total_price_usd,'USD'));if(x.total_price_rmb!=null)lines.push(manifestMoney(x.total_price_rmb,'RMB'));const bill=seaBilling(x);if(bill.amount!=null)lines.push(manifestMoney(bill.amount,bill.currency));if(!lines.length&&x.cost!=null)lines.push(money(packageValue(x)));return lines.join('<br>')||'—'}
function manifestLabel(label){const labels={'序号':'Manifest row','入仓日期':'Warehouse received date','入仓单号':'Warehouse receipt / tracking number','件数':'Pieces','重量':'Weight','体积':'Volume (CBM)','入库品名':'Item description','客户名':'Client name','装柜位置':'Container position','账单':'Calculated charge / billing formula'};return labels[label]||label}
function viewManifestDetails(id){const pkg=livePackageRows().find(x=>String(x.id)===String(id));if(!pkg)return toast('Package was not found. Refresh and try again.','error');const data=parseManifestData(pkg),columns=data.columns||{},metadata=data.metadata||{},bill=seaBilling(pkg),items=data.line_items||[];const section=(title,obj)=>Object.keys(obj).length?`<h3 style="margin:20px 0 8px">${esc(title)}</h3><div class="table-wrap"><table><tbody>${Object.entries(obj).map(([k,v])=>`<tr><th>${esc(manifestLabel(k))}</th><td>${esc(v??'—')}</td></tr>`).join('')}</tbody></table></div>`:'';const lines=items.length?`<h3 style="margin:20px 0 8px">Included warehouse receipt lines (${items.length})</h3><div class="table-wrap"><table><thead><tr><th>Receipt number</th><th>Pieces</th><th>Weight</th><th>CBM</th><th>Item</th></tr></thead><tbody>${items.map(item=>`<tr><td><b>${esc(item.warehouse_receipt_number)}</b></td><td>${esc(item.pcs??'—')}</td><td>${esc(item.weight??'—')}</td><td>${esc(item.volume_cbm??'—')}</td><td>${esc(item.description??'—')}</td></tr>`).join('')}</tbody></table></div>`:'';packageDialog(`<p class="eyebrow">DEX LOGISTICS · MANIFEST RECORD</p><h2>${esc(pkg.tracking_number||pkg.id)}</h2><p>${esc(pkg.consignee||'Unassigned client')} · ${esc(String(pkg.cargo_category||'general').toUpperCase())}</p>${bill.amount!=null?`<p><b>Calculated charge:</b> ${esc(manifestMoney(bill.amount,bill.currency))}${bill.raw?` · ${esc(bill.raw)}`:''}</p>`:''}${lines}${section('Manifest values',columns)}${section('Workbook details',metadata)}`)}
function packageTable(rows,title='Packages'){const canTrack=String(state.role||'').toLowerCase()!=='finance_manager';return `<section class="panel"><div class="panel-head"><div><h2>${esc(title)}</h2><p>${rows.length} live package${rows.length===1?'':'s'}</p></div></div><div class="table-wrap"><table><thead><tr><th>Tracking</th><th>Client</th><th>Category</th><th>Route / freight</th><th>Pieces</th><th>Weight / CBM</th><th>Manifest price</th><th>Status</th><th>Actions</th></tr></thead><tbody>${rows.map(x=>{const group=parseManifestData(x).group||{},lines=Number(group.line_count||0);return `<tr><td><b>${esc(x.tracking_number||x.id)}</b>${lines>1?`<br><small>${lines} cargo lines</small>`:''}</td><td>${esc(x.consignee)}${x.phone?`<br><small>${esc(x.phone)}</small>`:''}</td><td>${status(x.cargo_category||'general')}</td><td>${esc(x.origin||'—')} → ${esc(x.dest||'—')}<br><small>${esc(x.mode||'—')}${x.container_position?` · ${esc(x.container_position)}`:''}</small></td><td>${esc(x.pcs??'—')}</td><td>${esc(x.chargeable_weight??x.weight??'—')}${x.volume_cbm!=null?` kg<br><small>${esc(x.volume_cbm)} CBM</small>`:' kg'}</td><td>${packagePrice(x)}${x.payment_mode?`<br><small>${esc(x.payment_mode)}</small>`:''}</td><td>${status(x.status)}</td><td>${canTrack?`<button class="row-btn" data-external-track="${esc(x.id||x.tracking_number)}">Track</button> `:''}<button class="row-btn" onclick="viewManifestDetails('${String(x.id).replaceAll("'","\\'")}')">${lines>1?'View cargo':'Details'}</button> <button class="row-btn" data-reminder="${esc(x.id)}">Copy reminder</button> <button class="row-btn" data-track="${esc(x.id)}">Update</button></td></tr>`}).join('')||'<tr><td colspan="9" class="muted">No packages in this category.</td></tr>'}</tbody></table></div></section>`}
function shipments(){const all=livePackageRows(),selected=state.packageCategory||'all',rows=selected==='cleared'?all.filter(x=>['cleared','collected','released'].includes(String(x.status||'').toLowerCase())):selected==='all'?all:all.filter(x=>String(x.cargo_category||'general').toLowerCase()===selected),tabs=[['all','All packages'],['general','General'],['special','Special'],['sea','Sea'],['cleared','Cleared packages']];return `<section class="toolbar"><div class="search"><span>⌕</span><input id="shipment-search" placeholder="Search all packages, clients or tracking numbers" oninput="const q=this.value.toLowerCase().trim();document.querySelectorAll('.table-wrap tbody tr').forEach(row=>row.hidden=!!q&&!row.textContent.toLowerCase().includes(q))"></div><div class="category-tabs">${tabs.map(([key,label])=>`<button class="${selected===key?'active':''}" onclick="state.packageCategory='${key}';render()">${label}</button>`).join('')}</div><button class="primary" data-goto="manifests">⇧ Import manifest</button></section>${packageTable(rows,'Live packages')}`}
function renderManifestPreview(preview,form){const target=$('#manifest-preview');if(!target)return;const rows=preview.ready||[];target.innerHTML=`<section class="metrics" style="margin-top:18px">${metric('Rows found',preview.total_rows,'Excel rows read','blue')}${metric('Ready to register',preview.ready_rows,'Valid new packages','green')}${metric('Already registered',preview.duplicate_rows,'Skipped duplicates','amber')}${metric('Needs attention',preview.invalid_rows,'Not imported','red')}</section><section class="grid two"><article class="panel"><div class="panel-head"><div><h2>2. Review extracted packages</h2><p>All workbook columns will be retained; key commercial values are shown below.</p></div></div><div class="table-wrap"><table><thead><tr><th>Tracking</th><th>Client</th><th>PCS</th><th>Weight / CBM</th><th>Unit USD</th><th>RMB</th><th>USD</th><th>Calculated charge</th></tr></thead><tbody>${rows.map(r=>{const bill=seaBilling(r);return `<tr><td><b>${esc(r.tracking_number)}</b></td><td>${esc(r.consignee)}</td><td>${esc(r.pcs??'—')}</td><td>${esc(r.weight??'—')}${r.volume_cbm!=null?` / ${esc(r.volume_cbm)} CBM`:''}</td><td>${r.unit_price_usd==null?'—':manifestMoney(r.unit_price_usd,'USD')}</td><td>${r.total_price_rmb==null?'—':manifestMoney(r.total_price_rmb,'RMB')}</td><td>${r.total_price_usd==null?'—':manifestMoney(r.total_price_usd,'USD')}</td><td>${r.total_price_kes!=null?manifestMoney(r.total_price_kes,'KES'):bill.amount!=null?manifestMoney(bill.amount,bill.currency):'—'}${bill.raw?`<br><small>${esc(bill.raw)}</small>`:''}</td></tr>`}).join('')||'<tr><td colspan="8" class="muted">No new valid package rows to register.</td></tr>'}</tbody></table></div></article><article class="panel attention"><div class="panel-head"><div><h2>3. Confirm bulk registration</h2><p>Packages are saved in the shared backend and visible on all dashboards.</p></div></div><button class="primary wide" id="manifest-commit" ${preview.ready_rows?'':'disabled'}>Register ${preview.ready_rows||0} package(s)</button><p class="muted" style="margin-top:14px">Existing tracking IDs are safely skipped. KES amounts feed package value; RMB and USD remain exact source amounts.</p></article></section>`;$('#manifest-commit')?.addEventListener('click',async()=>{try{const result=await previewManifest(form,true);toast(`${result.imported_rows||0} packages were registered and are now available on dashboards.`);await refreshData()}catch(e){toast(`Manifest was not registered: ${e.message}`,'error')}})}

// Manifest preview uses FormData, so it cannot use the JSON adminRequest helper.
// Refresh the staff token once when a long-running session expires instead of
// leaving the user with an unexplained Unauthorized message.
async function previewManifest(form,commit=false,retried=false){const data=new FormData(form);data.set('commit',String(commit));const call=()=>fetch(`${ADMIN_BACKEND}/api/public/import-manifest`,{method:'POST',headers:{Authorization:`Bearer ${state.session.access_token}`},body:data});let response=await call();if(response.status===401&&!retried&&state.session?.refresh_token){const refresh=await fetch(`${state.connection.url}/auth/v1/token?grant_type=refresh_token`,{method:'POST',headers:{apikey:state.connection.key,'Content-Type':'application/json'},body:JSON.stringify({refresh_token:state.session.refresh_token})});if(refresh.ok){state.session=await refresh.json();await window.dexAdmin.saveSession(state.session);response=await call()}}const json=await response.json().catch(()=>({error:'The manifest service returned an unreadable response.'}));if(!response.ok)throw new Error(json.error||'Manifest import failed.');return json}

/* Final package, payment and tracking workspace.  These overrides sit last so
   they are the authoritative UI in the legacy single-file renderer. */
function isPaidPackage(pkg){return ['paid','cleared','collected','released'].includes(String(pkg?.status||'').toLowerCase())}
function packageState(pkg){return status(isPaidPackage(pkg)?'paid':'unpaid')}
function packageTable(rows,title='Packages'){return `<section class="panel"><div class="panel-head"><div><h2>${esc(title)}</h2><p>${rows.length} live package${rows.length===1?'':'s'}</p></div></div><div class="table-wrap"><table><thead><tr><th>Tracking</th><th>Client</th><th>Category</th><th>Route / freight</th><th>Pieces</th><th>Weight / CBM</th><th>Manifest price</th><th>Status</th><th>Actions</th></tr></thead><tbody>${rows.map(x=>{const group=parseManifestData(x).group||{},lines=Number(group.line_count||0);return `<tr><td><b>${esc(x.tracking_number||x.id)}</b>${lines>1?`<br><small>${lines} cargo lines</small>`:''}</td><td>${esc(x.consignee)}${x.phone?`<br><small>${esc(x.phone)}</small>`:''}</td><td>${status(x.cargo_category||'general')}</td><td>${esc(x.origin||'—')} → ${esc(x.dest||'—')}<br><small>${esc(x.mode||'—')}${x.container_position?` · ${esc(x.container_position)}`:''}</small></td><td>${esc(x.pcs??'—')}</td><td>${esc(x.chargeable_weight??x.weight??'—')}${x.volume_cbm!=null?` kg<br><small>${esc(x.volume_cbm)} CBM</small>`:' kg'}</td><td>${packagePrice(x)}${x.payment_mode?`<br><small>${esc(x.payment_mode)}</small>`:''}</td><td>${packageState(x)}</td><td><button class="row-btn" onclick="viewManifestDetails('${String(x.id).replaceAll("'","\\'")}')">${lines>1?'View cargo':'Details'}</button> <button class="row-btn" data-reminder="${esc(x.id)}">Copy reminder</button> <button class="row-btn" data-track="${esc(x.id)}">Update</button></td></tr>`}).join('')||'<tr><td colspan="9" class="muted">No packages in this category.</td></tr>'}</tbody></table></div></section>`}
function shipments(){const all=livePackageRows(),selected=state.packageCategory||'all',rows=selected==='paid'?all.filter(isPaidPackage):selected==='unpaid'?all.filter(x=>!isPaidPackage(x)):selected==='all'?all:all.filter(x=>String(x.cargo_category||'general').toLowerCase()===selected),tabs=[['all','All packages'],['general','General air'],['special','Special air'],['sea','Sea cargo'],['unpaid','Unpaid'],['paid','Paid']];return `<section class="toolbar"><div class="search"><span>⌕</span><input id="shipment-search" placeholder="Search all packages, clients or tracking numbers" oninput="const q=this.value.toLowerCase().trim();document.querySelectorAll('.table-wrap tbody tr').forEach(row=>row.hidden=!!q&&!row.textContent.toLowerCase().includes(q))"></div><div class="category-tabs">${tabs.map(([key,label])=>`<button class="${selected===key?'active':''}" onclick="state.packageCategory='${key}';render()">${label}</button>`).join('')}</div><button class="primary" data-goto="manifests">⇧ Import manifest</button></section>${packageTable(rows,'Live packages')}`}
function paymentLinkDialog(id){const evidence=(state.data.notifications||[]).find(x=>String(x.id)===String(id));const packages=livePackageRows().filter(x=>!isPaidPackage(x));if(!evidence)return toast('Payment evidence was not found. Refresh and try again.','error');if(!packages.length)return toast('There are no unpaid packages available to link.','error');const modal=packageDialog(`<p class="eyebrow">DEX LOGISTICS · PAYMENT RECONCILIATION</p><h2>Link payment evidence</h2><p>Select one or multiple unpaid packages. Every selected package will move to <b>Paid</b>.</p><div class="package-link-list">${packages.map(p=>`<label class="check-row"><input type="checkbox" value="${esc(p.id)}" data-payment-package> <span><b>${esc(p.tracking_number||p.id)}</b><small>${esc(p.consignee||'Unassigned client')} · ${packagePrice(p)}</small></span></label>`).join('')}</div><div class="dialog-actions"><button class="primary" data-confirm-payment-link>Link selected packages</button><button class="secondary" data-close-payment-link>Cancel</button></div>`);modal.querySelector('[data-close-payment-link]').onclick=()=>modal.remove();modal.querySelector('[data-confirm-payment-link]').onclick=async(button)=>{const chosen=[...modal.querySelectorAll('[data-payment-package]:checked')].map(x=>x.value);if(!chosen.length)return toast('Select at least one package.','error');button.currentTarget.disabled=true;try{await adminRequest('/api/public/link-payment',{method:'POST',body:JSON.stringify({payment_notification_id:id,allocations:chosen.map(package_id=>({package_id}))})});modal.remove();toast(`${chosen.length} package${chosen.length===1?'':'s'} marked Paid.`);await refreshData()}catch(e){button.currentTarget.disabled=false;toast(`Payment link failed: ${e.message}`,'error')}}}

// DEX payment release override.  All status changes go through the secured
// backend, then the live package list is reloaded.  This prevents a package
// from appearing paid only on the desktop that performed the action.
function releasePackage(id){
  const pkg=livePackageRows().find(x=>String(x.id)===String(id));
  if(!pkg)return toast('Package was not found. Refresh and try again.','error');
  if(isPaidPackage(pkg))return toast('This package is already paid.','error');
  const group=parseManifestData(pkg).group||{};
  const lineCount=Number(group.line_count||group.line_items?.length||0);
  const modal=packageDialog(`<p class="eyebrow">DEX LOGISTICS · PAYMENT RELEASE</p>
    <h2>Release ${esc(pkg.tracking_number||pkg.id)}</h2>
    <p>Confirm that payment has been collected. The backend will mark this package <b>Paid</b> and refresh company revenue.</p>
    <div class="release-summary"><div><small>Client</small><b>${esc(pkg.consignee||'Not provided')}</b></div><div><small>Package value</small><b>${packagePrice(pkg)}</b></div>${lineCount>1?`<div><small>Grouped cargo lines</small><b>${lineCount} lines released together</b></div>`:''}</div>
    <form id="release-package-form" class="release-form">
      <label>Payment method<select name="payment_method" required><option value="cash">Cash</option><option value="mpesa">M-Pesa</option><option value="bank_transfer">Bank transfer</option><option value="other">Other</option></select></label>
      <label>Payment reference<input name="payment_reference" placeholder="Receipt, M-Pesa code, or bank reference"></label>
      <label>Collection note <textarea name="note" placeholder="Optional note for the audit log"></textarea></label>
      <p class="muted">For a payment screenshot or message, upload it under Payments and use “Link package(s)”.</p>
      <div class="dialog-actions"><button class="primary" type="submit">Confirm release and mark paid</button><button class="secondary" type="button" data-cancel-release>Cancel</button></div>
    </form>`);
  modal.querySelector('[data-cancel-release]').onclick=()=>modal.remove();
  modal.querySelector('#release-package-form').addEventListener('submit',async event=>{
    event.preventDefault();
    const form=new FormData(event.currentTarget);
    const button=event.currentTarget.querySelector('button[type="submit"]');
    button.disabled=true;button.textContent='Confirming payment…';
    try{
      const result=await adminRequest(`/api/public/packages/${encodeURIComponent(pkg.id)}/mark-paid`,{method:'POST',body:JSON.stringify({payment_method:form.get('payment_method'),payment_reference:form.get('payment_reference'),note:form.get('note')})});
      if(result?.ok===false)throw new Error(result.error||'The backend did not confirm payment.');
      modal.remove();
      toast(result?.already_paid?'Package was already paid.':'Package marked paid and cleared for release.');
      await refreshData();
    }catch(error){
      button.disabled=false;button.textContent='Confirm release and mark paid';
      toast(`Package release failed: ${error.message}`,'error');
    }
  });
}

function packageTable(rows,title='Packages'){
  const canRelease=['admin','logistics_manager','sales_manager'].includes(String(state.role||'').toLowerCase());
  return `<section class="panel"><div class="panel-head"><div><h2>${esc(title)}</h2><p>${rows.length} live package${rows.length===1?'':'s'}</p></div></div><div class="table-wrap"><table><thead><tr><th>Tracking</th><th>Client</th><th>Category</th><th>Route / freight</th><th>Pieces</th><th>Weight / CBM</th><th>Manifest price</th><th>Status</th><th>Actions</th></tr></thead><tbody>${rows.map(x=>{const group=parseManifestData(x).group||{},lines=Number(group.line_count||group.line_items?.length||0),paid=isPaidPackage(x);return `<tr><td><b>${esc(x.tracking_number||x.id)}</b>${lines>1?`<br><small>${lines} cargo lines</small>`:''}</td><td>${esc(x.consignee)}${x.phone?`<br><small>${esc(x.phone)}</small>`:''}</td><td>${status(x.cargo_category||'general')}</td><td>${esc(x.origin||'—')} → ${esc(x.dest||'—')}<br><small>${esc(x.mode||'—')}${x.container_position?` · ${esc(x.container_position)}`:''}</small></td><td>${esc(x.pcs??'—')}</td><td>${esc(x.chargeable_weight??x.weight??'—')}${x.volume_cbm!=null?` kg<br><small>${esc(x.volume_cbm)} CBM</small>`:' kg'}</td><td>${packagePrice(x)}${x.payment_mode?`<br><small>${esc(x.payment_mode)}</small>`:''}</td><td>${packageState(x)}</td><td><button class="row-btn" onclick="viewManifestDetails('${String(x.id).replaceAll("'","\\'")}')">${lines>1?'View cargo':'Details'}</button> <button class="row-btn" data-reminder="${esc(x.id)}">Copy reminder</button> ${canRelease&&!paid?`<button class="row-btn approve" onclick="releasePackage('${String(x.id).replaceAll("'","\\'")}')">Release</button> `:''}<button class="row-btn" data-track="${esc(x.id)}">Update</button></td></tr>`}).join('')||'<tr><td colspan="9" class="muted">No packages in this category.</td></tr>'}</tbody></table></div></section>`;
}
async function linkPayment(id){paymentLinkDialog(id)}
function payments(){const rows=state.data.notifications||[];return `<section class="panel compose"><div class="panel-head"><div><h2>Upload payment evidence</h2><p>Upload an image with an optional note, or a text payment message.</p></div></div><form id="payment-upload"><label>Evidence type<select id="evidence-type" name="evidence_type"><option value="IMAGE">Payment screenshot</option><option value="TEXT">Text payment message</option></select></label><label id="image-field">Screenshot<input name="image" type="file" accept="image/*"></label><label id="note-field">Note attached to image (optional)<textarea name="image_note" placeholder="Optional internal note"></textarea></label><label id="text-field" style="display:none">Payment message<textarea name="text_content" placeholder="Paste the M-Pesa / payment message"></textarea></label><button class="primary" type="submit">Save payment evidence to backend</button></form></section><section class="panel"><div class="panel-head"><div><h2>Payment evidence queue</h2><p>Link one evidence record to one or multiple unpaid packages.</p></div><span class="count">${rows.length} records</span></div><div class="table-wrap"><table><thead><tr><th>Reference</th><th>Evidence</th><th>Details</th><th>Status</th><th>Action</th></tr></thead><tbody>${rows.map(x=>`<tr><td><b>${esc(x.notification_number||x.id)}</b></td><td>${x.image_url?`<button class="evidence-preview" data-evidence-image="${esc(x.image_url)}"><img data-evidence-thumb="${esc(x.image_url)}" alt="Payment evidence"><span>View image</span></button>`:`<button class="row-btn" data-evidence-text="${esc(x.text_content||'No payment message was attached.')}">View text</button>`}</td><td><div class="evidence-note">${esc(x.text_content||'No note attached')}</div></td><td>${status(x.status)}</td><td><button class="row-btn" data-link-payment="${esc(x.id)}">Link package(s)</button></td></tr>`).join('')||'<tr><td colspan="5" class="empty">No payment evidence has been uploaded yet.</td></tr>'}</tbody></table></div></section>`}
function trackerView(){return `<section class="role-banner compact"><div><span>DEX LOGISTICS · TRACKING</span><h2>Package tracking service</h2><p>Enter any tracking number. DEX checks its internal timeline first and gives 17TRACK and ParcelsApp as reliable fallbacks.</p></div></section><section class="panel compose"><form id="standalone-tracker"><label>Tracking number<input name="number" required autocomplete="off" placeholder="e.g. 1260818949397"></label><button class="primary" type="submit">Track package</button></form><div id="standalone-tracking-result"></div></section>`}
async function runStandaloneTracking(form){const number=String(new FormData(form).get('number')||'').trim(),target=$('#standalone-tracking-result');if(!number)return;target.innerHTML='<p class="muted" style="margin-top:18px">Checking DEX and carrier sources…</p>';try{const result=await adminRequest(`/api/public/track?number=${encodeURIComponent(number)}`),events=(result.events||[]).slice(0,12).map(e=>`<div class="action"><span>◉</span><div><b>${esc(e.status||'Update')}</b><small>${esc(e.location||'')} · ${esc(e.time?date(e.time):'')}</small></div></div>`).join('')||'<p class="muted">No carrier checkpoints have been returned yet.</p>';target.innerHTML=`<div class="panel" style="margin-top:18px"><h2>${esc(number)}</h2><p><b>${esc(result.latest_status||'No external update')}</b></p>${events}<div class="dialog-actions"><button class="row-btn" data-tracker-provider="17track">Open 17TRACK</button><button class="row-btn" data-tracker-provider="parcels">Open ParcelsApp</button></div></div>`;target.querySelectorAll('[data-tracker-provider]').forEach(b=>b.onclick=()=>openTrackingProvider(b.dataset.trackerProvider,number))}catch(e){target.innerHTML=`<p class="muted" style="margin-top:18px">DEX tracking could not be reached: ${esc(e.message)}.</p><button class="row-btn" data-tracker-provider="17track">Open 17TRACK</button> <button class="row-btn" data-tracker-provider="parcels">Open ParcelsApp</button>`;target.querySelectorAll('[data-tracker-provider]').forEach(b=>b.onclick=()=>openTrackingProvider(b.dataset.trackerProvider,number))}}
function navItems(role){const manifest=['manifests','Import manifest','⇧'],tracker=['tracking','Track package','⌕'];const admin=[['overview','Overview','◫'],['shipments','Packages','▣'],manifest,tracker,['payments','Payments','◉'],['staff','Staff','♙'],['commissions','Commissions','◈'],['announcements','Announcements','◌'],['audit','Audit log','◷']];const salesRep=[['overview','My overview','◫'],['my_packages','My packages','▣'],tracker,manifest,['reminders','Client reminders','◌'],['my_commissions','My commissions','◈'],['announcements','Announcements','◌']];const salesManager=[['overview','Sales overview','◫'],['sales_packages','Sales packages','▣'],tracker,manifest,['team_performance','Team performance','◈'],['commissions','Team commissions','◈'],['announcements','Announcements','◌']];const logistics=[['overview','Warehouse overview','◫'],['warehouse_packages','Warehouse packages','▣'],tracker,manifest,['payments','Payment evidence','◉'],['release_queue','Release queue','✓'],['announcements','Announcements','◌']];const finance=[['overview','Finance overview','◫'],['finance_invoices','Invoices & billing','▣'],['payments','Payment evidence','◉'],['finance_receivables','Receivables','◈'],['finance_expenses','Expenses','◌'],['finance_payables','Payables','◌'],['finance_profitability','Package profitability','◫'],['finance_tax','KRA & tax','✓'],['finance_reports','Reports','◷'],manifest];return role==='admin'?admin:role==='sales_rep'?salesRep:role==='sales_manager'?salesManager:role==='logistics_manager'?logistics:finance}
function pageTitle(){const labels={tracking:'Track package',overview:'Overview',manifests:'Manifest import',my_packages:'My packages',reminders:'Client reminders',my_commissions:'My commissions',sales_packages:'Sales packages',team_performance:'Team performance',warehouse_packages:'Warehouse packages',release_queue:'Release queue',finance_invoices:'Invoices & billing',finance_receivables:'Receivables',finance_expenses:'Expenses',finance_payables:'Payables',finance_profitability:'Package profitability',finance_tax:'KRA & tax',finance_reports:'Reports',shipments:'Packages',payments:'Payments',staff:'Staff',commissions:'Commissions',announcements:'Announcements',audit:'Audit log'};return labels[state.page]||'DEX Admin'}
function roleContent(){const role=state.role;if(state.page==='tracking'&&role!=='finance_manager')return trackerView();if(state.page==='manifests')return manifestView();if(role==='admin'){const views={overview,shipments,payments,staff,commissions,announcements,audit};return (views[state.page]||overview)()}if(state.page==='overview')return departmentOverview();if(role==='sales_rep'){if(state.page==='my_packages')return departmentPackages('My assigned packages',myPackages());if(state.page==='reminders')return remindersView();if(state.page==='my_commissions')return commissions()}if(role==='sales_manager'){if(state.page==='sales_packages')return departmentPackages('Sales packages',state.data.packages||[]);if(state.page==='team_performance')return performanceView();if(state.page==='commissions')return commissions()}if(role==='logistics_manager'){if(state.page==='warehouse_packages')return departmentPackages('Warehouse packages',state.data.packages||[]);if(state.page==='payments')return payments();if(state.page==='release_queue')return releaseQueue()}if(role==='finance_manager'){if(state.page==='payments')return payments();return financeView(state.page)}return departmentOverview()}
function openShipment(id){const pkg=(state.data.packages||[]).find(x=>String(x.id)===String(id));if(!pkg)return toast('Package was not found. Refresh and try again.','error');const currentlyPaid=isPaidPackage(pkg),modal=packageDialog(`<p class="eyebrow">DEX LOGISTICS · PACKAGE STATUS</p><h2>Update ${esc(pkg.tracking_number||pkg.id)}</h2><p>DEX uses two states only. Paid means cleared and ready for the customer.</p><div class="status-actions"><button class="row-btn ${!currentlyPaid?'selected-status':''}" data-package-state="unpaid">Unpaid</button><button class="row-btn ${currentlyPaid?'selected-status':''}" data-package-state="paid">Paid</button></div>`);modal.querySelectorAll('[data-package-state]').forEach(button=>button.onclick=async()=>{const selected=button.dataset.packageState,patch={status:selected};if(selected==='paid')patch.paid_at=pkg.paid_at||new Date().toISOString();try{button.disabled=true;await request(`rest/v1/cargo_packages?id=eq.${encodeURIComponent(pkg.id)}`,{method:'PATCH',headers:{Prefer:'return=representation'},body:JSON.stringify(patch)});modal.remove();toast(`Package marked ${selected}.`);await refreshData()}catch(e){button.disabled=false;toast(`Package update failed: ${e.message}`,'error')}})}
function bind(){document.querySelectorAll('[data-page],[data-goto]').forEach(b=>b.addEventListener('click',()=>{state.page=b.dataset.page||b.dataset.goto;render()}));$('#refresh')?.addEventListener('click',refreshData);$('#signout')?.addEventListener('click',async()=>{await window.dexAdmin.clearSession();state.session=null;state.data={};renderLogin()});$('#add-staff')?.addEventListener('click',createEmployee);$('#payment-upload')?.addEventListener('submit',e=>{e.preventDefault();uploadPayment(e.target)});$('#evidence-type')?.addEventListener('change',e=>{const image=e.target.value==='IMAGE';$('#image-field').style.display=image?'':'none';$('#note-field').style.display=image?'':'none';$('#text-field').style.display=image?'none':''});$('#manifest-form')?.addEventListener('submit',async e=>{e.preventDefault();const button=e.target.querySelector('button');try{button.disabled=true;button.textContent='Reading manifest…';renderManifestPreview(await previewManifest(e.target,false),e.target)}catch(err){toast(`Manifest preview failed: ${err.message}`,'error')}finally{button.disabled=false;button.textContent='Read and preview manifest'}});$('#standalone-tracker')?.addEventListener('submit',e=>{e.preventDefault();runStandaloneTracking(e.target)});document.querySelectorAll('[data-evidence-image]').forEach(b=>b.addEventListener('click',()=>viewEvidenceImage(b.dataset.evidenceImage)));document.querySelectorAll('[data-evidence-thumb]').forEach(loadEvidenceThumbnail);document.querySelectorAll('[data-evidence-text]').forEach(b=>b.addEventListener('click',()=>viewEvidenceText(b.dataset.evidenceText)));document.querySelectorAll('[data-delete-employee]').forEach(b=>b.addEventListener('click',()=>deleteEmployee(b.dataset.deleteEmployee)));document.querySelectorAll('[data-link-payment]').forEach(b=>b.addEventListener('click',()=>linkPayment(b.dataset.linkPayment)));document.querySelectorAll('[data-employee]').forEach(b=>b.addEventListener('click',()=>setEmployee(b.dataset.employee,b.dataset.active!=='true')));document.querySelectorAll('[data-commission]').forEach(b=>b.addEventListener('click',()=>commission(b.dataset.commission,'approve_commission')));document.querySelectorAll('[data-paid]').forEach(b=>b.addEventListener('click',()=>commission(b.dataset.paid,'mark_commission_paid')));document.querySelectorAll('[data-track]').forEach(b=>b.addEventListener('click',()=>openShipment(b.dataset.track)));document.querySelectorAll('[data-reminder]').forEach(b=>b.addEventListener('click',()=>copyReminder(b.dataset.reminder)));$('#broadcast-form')?.addEventListener('submit',sendBroadcast);$('#export-audit')?.addEventListener('click',exportAudit)}

// Final operational overrides for the current installer build.
// Keep the package actions backed by the release endpoint rather than an
// optimistic direct Supabase PATCH.
function openShipment(id){
  const pkg=livePackageRows().find(x=>String(x.id)===String(id));
  if(!pkg)return toast('Package was not found. Refresh and try again.','error');
  const modal=packageDialog(`<p class="eyebrow">DEX LOGISTICS · PACKAGE STATUS</p><h2>Update ${esc(pkg.tracking_number||pkg.id)}</h2><p>Payment status is set through the Release action. Use this screen only to review the current backend state.</p><div class="status-actions"><span>${packageState(pkg)}</span></div><div class="dialog-actions"><button class="secondary" data-close-update>Close</button></div>`);
  modal.querySelector('[data-close-update]').onclick=()=>modal.remove();
}

// Last definitions in this legacy renderer are authoritative.  The previous
// Update popup directly patched cargo_packages; this version never does.
function packageTable(rows,title='Packages'){
  const canRelease=['admin','logistics_manager','sales_manager'].includes(String(state.role||'').toLowerCase());
  return `<section class="panel"><div class="panel-head"><div><h2>${esc(title)}</h2><p>${rows.length} live package${rows.length===1?'':'s'}</p></div></div><div class="table-wrap"><table><thead><tr><th>Tracking</th><th>Client</th><th>Category</th><th>Route / freight</th><th>Pieces</th><th>Weight / CBM</th><th>Manifest price</th><th>Status</th><th>Actions</th></tr></thead><tbody>${rows.map(x=>{const group=parseManifestData(x).group||{},lines=Number(group.line_count||group.line_items?.length||0),paid=isPaidPackage(x);return `<tr><td><b>${esc(x.tracking_number||x.id)}</b>${lines>1?`<br><small>${lines} cargo lines</small>`:''}</td><td>${esc(x.consignee)}${x.phone?`<br><small>${esc(x.phone)}</small>`:''}</td><td>${status(x.cargo_category||'general')}</td><td>${esc(x.origin||'—')} → ${esc(x.dest||'—')}<br><small>${esc(x.mode||'—')}${x.container_position?` · ${esc(x.container_position)}`:''}</small></td><td>${esc(x.pcs??'—')}</td><td>${esc(x.chargeable_weight??x.weight??'—')}${x.volume_cbm!=null?` kg<br><small>${esc(x.volume_cbm)} CBM</small>`:' kg'}</td><td>${packagePrice(x)}${x.payment_mode?`<br><small>${esc(x.payment_mode)}</small>`:''}</td><td>${packageState(x)}</td><td><button class="row-btn" onclick="viewManifestDetails('${String(x.id).replaceAll("'","\\'")}')">${lines>1?'View cargo':'Details'}</button> <button class="row-btn" data-reminder="${esc(x.id)}">Copy reminder</button> ${canRelease&&!paid?`<button class="row-btn approve" onclick="releasePackage('${String(x.id).replaceAll("'","\\'")}')">Release</button> `:''}<button class="row-btn" data-track="${esc(x.id)}">Update</button></td></tr>`}).join('')||'<tr><td colspan="9" class="muted">No packages in this category.</td></tr>'}</tbody></table></div></section>`;
}

function shipments(){
  const all=livePackageRows(),selected=state.packageCategory||'all';
  const rows=selected==='paid'?all.filter(isPaidPackage):selected==='unpaid'?all.filter(x=>!isPaidPackage(x)):selected==='all'?all:all.filter(x=>String(x.cargo_category||'general').toLowerCase()===selected);
  const tabs=[['all','All packages'],['general','General'],['special','Special'],['sea','Sea'],['unpaid','Unpaid'],['paid','Paid']];
  return `<section class="toolbar"><div class="search"><span>⌕</span><input id="shipment-search" placeholder="Search all packages, clients or tracking numbers" oninput="const q=this.value.toLowerCase().trim();document.querySelectorAll('.table-wrap tbody tr').forEach(row=>row.hidden=!!q&&!row.textContent.toLowerCase().includes(q))"></div><div class="category-tabs">${tabs.map(([key,label])=>`<button class="${selected===key?'active':''}" onclick="state.packageCategory='${key}';render()">${label}</button>`).join('')}</div><button class="primary" data-goto="manifests">⇧ Import manifest</button></section>${packageTable(rows,'Live packages')}`;
}
